require("dotenv").config();
const prisma = require("../../config/prisma");
const bcrypt = require("bcryptjs");
const jwt = require("jsonwebtoken");
const crypto = require("crypto");
const emailService = require("../../services/email/email.service");
const validatePassword = require("./security/validatePassword");
const { ETUDIANT } = require("../../constants/roles");

const normalize = (v) => String(v || "").trim().toUpperCase();

// ── Réinitialisation par code OTP ──
// Jeu de caractères sans ambiguïté visuelle (pas de I, L, O, 0, 1)
const RESET_CODE_CHARS = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
const RESET_CODE_LENGTH = 6;
const RESET_CODE_TTL_MS = 10 * 60 * 1000; // 10 minutes

/**
 * Génère un code de réinitialisation aléatoire (6 caractères alphanumériques majuscules).
 * @returns {string} ex: "K7P2QM"
 */
const generateResetCode = () => {
  const bytes = crypto.randomBytes(RESET_CODE_LENGTH);
  let code = "";
  for (let i = 0; i < RESET_CODE_LENGTH; i++) {
    code += RESET_CODE_CHARS[bytes[i] % RESET_CODE_CHARS.length];
  }
  return code;
};

const REQUIRE_EMAIL_VERIFICATION =
  String(process.env.REQUIRE_EMAIL_VERIFICATION ?? "true").toLowerCase() !==
  "false";

const ALLOW_UNVERIFIED_DEV_LOGIN =
  String(process.env.ALLOW_UNVERIFIED_DEV_LOGIN || "false").toLowerCase() ===
  "true";

// ✅ Token JWT (on ajoute institutionCode)
const genToken = (user) =>
  jwt.sign(
    {
      id: user.id,
      role: user.role,
      institutionId: user.institutionId ?? null,
      institutionCode: user.institution?.sigle || null,
      service: user.service ?? null,
    },
    process.env.JWT_SECRET,
    { expiresIn: process.env.JWT_EXPIRES_IN || "7d" }
  );

async function resolveInstitutionId({ institutionId, institutionSigle }) {
  const raw = (institutionId ?? institutionSigle ?? "IFRI").toString().trim();

  const value = raw.trim();
  const sigle = normalize(value);

  const inst = await prisma.institution.findFirst({
    where: {
      OR: [{ id: value }, { sigle }, { nom: { equals: value, mode: "insensitive" } }],
    },
    select: { id: true, nom: true, sigle: true },
  });

  if (!inst) {
    const err = new Error(
      `Institution inconnue: "${value}". Envoie un UUID valide ou un sigle existant (ex: IFRI).`
    );
    err.statusCode = 400;
    throw err;
  }

  return inst.id;
}

exports.register = async ({
  nom,
  prenom,
  email,
  password,
  numeroEtudiant,
  institutionId,
  institutionSigle,
  filiere,
  niveau,
}) => {
  if (!nom || !prenom || !email || !password) {
    const err = new Error("Champs requis: nom, prenom, email, password.");
    err.statusCode = 400;
    throw err;
  }

  validatePassword(password);

  const cleanEmail = String(email).trim().toLowerCase();

  const existing = await prisma.utilisateur.findUnique({
    where: { email: cleanEmail },
    select: { id: true },
  });

  if (existing) {
    const err = new Error("Cet email est déjà utilisé");
    err.statusCode = 400;
    throw err;
  }

  if (numeroEtudiant) {
    const already = await prisma.utilisateur.findFirst({
      where: { numeroEtudiant: String(numeroEtudiant).trim() },
      select: { id: true },
    });

    if (already) {
      const err = new Error("Ce numéro étudiant est déjà utilisé.");
      err.statusCode = 400;
      throw err;
    }
  }

  const resolvedInstitutionId = await resolveInstitutionId({
    institutionId,
    institutionSigle,
  });

  // ✅ Institution obligatoire (MVP multi-institutions)
  if (!resolvedInstitutionId) {
    const err = new Error(
      "Institution obligatoire. Fournis institutionId ou institutionSigle (IFRI/EPAC/FSS)."
    );
    err.statusCode = 400;
    throw err;
  }

  const hash = await bcrypt.hash(password, 12);

  const tokenVerification = REQUIRE_EMAIL_VERIFICATION
    ? crypto.randomBytes(32).toString("hex")
    : null;

  const created = await prisma.utilisateur.create({
    data: {
      nom: String(nom).trim(),
      prenom: String(prenom).trim(),
      email: cleanEmail,
      password: hash,
      role: ETUDIANT,
      numeroEtudiant: numeroEtudiant ? String(numeroEtudiant).trim() : null,
      filiere: filiere ? String(filiere).trim() : null,
      niveau: niveau ? String(niveau).trim() : null,
      institutionId: resolvedInstitutionId,
      tokenVerification: tokenVerification ? await bcrypt.hash(tokenVerification, 12) : null,
      emailVerifie: REQUIRE_EMAIL_VERIFICATION ? false : true,
      actif: REQUIRE_EMAIL_VERIFICATION ? false : true,
    },
    select: { id: true, email: true },
  });

  if (REQUIRE_EMAIL_VERIFICATION && tokenVerification) {
    if (!emailService.isEmailDeliveryConfigured()) {
      await prisma.utilisateur.delete({ where: { id: created.id } }).catch(() => {});
      const err = new Error(
        "Service email non configure. Configurez SMTP_HOST, SMTP_PORT, SMTP_USER et SMTP_PASS avant de creer un compte."
      );
      err.statusCode = 503;
      err.code = "EMAIL_NOT_CONFIGURED";
      err.expose = true;
      throw err;
    }

    try {
      await emailService.sendVerificationEmailRequired(created.email, tokenVerification);
    } catch (e) {
      await prisma.utilisateur.delete({ where: { id: created.id } }).catch(() => {});
      const err = new Error(
        "Impossible d'envoyer l'email de confirmation. Verifiez la configuration SMTP puis reessayez."
      );
      err.statusCode = 503;
      err.code = "EMAIL_DELIVERY_FAILED";
      err.expose = true;
      throw err;
    }
  }

  return {
    message: REQUIRE_EMAIL_VERIFICATION
      ? "Compte créé. Vérifiez votre email."
      : "Compte créé (mode DEV). Vous pouvez vous connecter directement.",
  };
};

exports.login = async ({ email, password }) => {
  const cleanEmail = String(email || "").trim().toLowerCase();

  const user = await prisma.utilisateur.findUnique({
    where: { email: cleanEmail },
    include: {
      institution: {
        select: { id: true, nom: true, sigle: true, logoUrl: true },
      },
    },
  });

  if (!user) {
    // Simuler le temps bcrypt pour éviter les timing attacks
    await bcrypt.compare(password, "$2a$12$fakehashfakehashfakehashfakehash");
    const err = new Error("Email ou mot de passe incorrect");
    err.statusCode = 401;
    throw err;
  }

  if (REQUIRE_EMAIL_VERIFICATION && !user.emailVerifie) {
    const err = new Error("Email non vérifié");
    err.statusCode = 403;
    err.code = "EMAIL_NOT_VERIFIED";
    throw err;
  }

  if (REQUIRE_EMAIL_VERIFICATION && !user.actif) {
    const err = new Error("Compte désactivé");
    err.statusCode = 403;
    throw err;
  }

  const valid = await bcrypt.compare(password, user.password);
  if (!valid) {
    const err = new Error("Email ou mot de passe incorrect");
    err.statusCode = 401;
    throw err;
  }

  if (
    ALLOW_UNVERIFIED_DEV_LOGIN &&
    !REQUIRE_EMAIL_VERIFICATION &&
    user.role === ETUDIANT &&
    (!user.emailVerifie || !user.actif)
  ) {
    await prisma.utilisateur.update({
      where: { id: user.id },
      data: { emailVerifie: true, actif: true, tokenVerification: null },
    });
    user.emailVerifie = true;
    user.actif = true;
  }

  const token = genToken(user);

  const institutionCode = user.institution?.sigle || null;

  // ✅ Le front reçoit tout pour adapter l'UI directement
  return {
    token,
    user: {
      id: user.id,
      nom: user.nom,
      prenom: user.prenom,
      email: user.email,
      role: user.role,
      service: user.service,
      institutionId: user.institutionId,
      institutionCode,
      numeroEtudiant: user.numeroEtudiant,
      filiere: user.filiere,
      niveau: user.niveau,
      institution: user.institution,
    },
  };
};

exports.verifyEmail = async (token, email) => {
  const cleanEmail = String(email || "").trim().toLowerCase();

  const user = await prisma.utilisateur.findUnique({
    where: { email: cleanEmail },
    select: { id: true, tokenVerification: true, emailVerifie: true },
  });

  if (!user || !user.tokenVerification) {
    const err = new Error("Token invalide");
    err.statusCode = 400;
    throw err;
  }

  const isValid = await bcrypt.compare(token, user.tokenVerification);
  if (!isValid) {
    const err = new Error("Token invalide");
    err.statusCode = 400;
    throw err;
  }

  await prisma.utilisateur.update({
    where: { id: user.id },
    data: { emailVerifie: true, actif: true, tokenVerification: null },
  });

  return { message: "Email vérifié. Vous pouvez vous connecter." };
};

exports.requestPasswordReset = async (email) => {
  const cleanEmail = String(email || "").trim().toLowerCase();

  const user = await prisma.utilisateur.findUnique({
    where: { email: cleanEmail },
    select: { id: true, email: true },
  });

  // Réponse identique que l'email existe ou non (anti-énumération)
  if (!user) return { message: "Si cet email existe, un code a été envoyé." };

  const code = generateResetCode();
  const hashedCode = await bcrypt.hash(code, 12);

  await prisma.utilisateur.update({
    where: { id: user.id },
    data: {
      tokenResetPassword: hashedCode,
      tokenResetExpiry: new Date(Date.now() + RESET_CODE_TTL_MS),
    },
  });

  try {
    await emailService.sendPasswordResetEmail(cleanEmail, code);
  } catch (e) {
    console.log("[EMAIL SKIPPED]", e.message);
  }

  return { message: "Si cet email existe, un code a été envoyé." };
};

exports.resetPassword = async (email, code, newPassword) => {
  validatePassword(newPassword);

  const cleanEmail = String(email || "").trim().toLowerCase();
  const cleanCode = String(code || "").trim().toUpperCase();

  if (cleanCode.length !== RESET_CODE_LENGTH) {
    const err = new Error("Code invalide ou expiré");
    err.statusCode = 400;
    throw err;
  }

  const user = await prisma.utilisateur.findUnique({
    where: { email: cleanEmail },
    select: { id: true, tokenResetPassword: true, tokenResetExpiry: true },
  });

  if (!user || !user.tokenResetPassword || user.tokenResetExpiry < new Date()) {
    const err = new Error("Code invalide ou expiré");
    err.statusCode = 400;
    throw err;
  }

  const isValid = await bcrypt.compare(cleanCode, user.tokenResetPassword);
  if (!isValid) {
    const err = new Error("Code invalide ou expiré");
    err.statusCode = 400;
    throw err;
  }

  const hash = await bcrypt.hash(newPassword, 12);

  await prisma.utilisateur.update({
    where: { id: user.id },
    data: { password: hash, tokenResetPassword: null, tokenResetExpiry: null },
  });

  return { message: "Mot de passe réinitialisé." };
};

exports.changePassword = async (userId, currentPassword, newPassword) => {
  validatePassword(newPassword);

  const user = await prisma.utilisateur.findUnique({
    where: { id: userId },
    select: { id: true, password: true },
  });

  if (!user) {
    const err = new Error("Utilisateur introuvable");
    err.statusCode = 404;
    throw err;
  }

  const isValid = await bcrypt.compare(currentPassword, user.password);
  if (!isValid) {
    const err = new Error("Mot de passe actuel incorrect");
    err.statusCode = 400;
    throw err;
  }

  const hash = await bcrypt.hash(newPassword, 12);

  await prisma.utilisateur.update({
    where: { id: user.id },
    data: { password: hash },
  });

  return { message: "Mot de passe modifié avec succès" };
};

// src/modules/auth/security/validatePassword.js

/**
 * Valide un mot de passe selon les règles définies.
 * @param {string} password - Le mot de passe à valider.
 * @returns {boolean} - True si valide, sinon lève une erreur.
 * @throws {Error} - Erreur avec statusCode si invalide.
 */
function validatePassword(password) {
  if (!password || typeof password !== 'string') {
    const err = new Error('Mot de passe requis.');
    err.statusCode = 400;
    throw err;
  }

  const manquants = [];
  if (password.length < 8) manquants.push('au moins 8 caractères');
  if (!/[A-Z]/.test(password)) manquants.push('une lettre majuscule');
  if (!/[^A-Za-z0-9]/.test(password)) manquants.push('un caractère spécial');

  if (manquants.length > 0) {
    const err = new Error(`Le mot de passe doit contenir ${manquants.join(', ')}.`);
    err.statusCode = 400;
    throw err;
  }

  return true;
}

module.exports = validatePassword;

