require("dotenv").config();
const nodemailer = require("nodemailer");
const ejs = require("ejs");
const path = require("path");
const fs = require("fs");

const FROM = process.env.MAIL_FROM || '"EtuDocs" <noreply@etudocs.uac.bj>';

const isDev = (process.env.NODE_ENV || "development") !== "production";
const SMTP_HOST = process.env.SMTP_HOST || process.env.BREVO_SMTP_HOST;
const SMTP_PORT = process.env.SMTP_PORT || process.env.BREVO_SMTP_PORT;
const SMTP_USER = process.env.SMTP_USER || process.env.BREVO_SMTP_USER;
const SMTP_PASS = process.env.SMTP_PASS || process.env.BREVO_SMTP_PASS;

const hasSmtpConfig =
  !!SMTP_HOST &&
  !!SMTP_PORT &&
  !!SMTP_USER &&
  !!SMTP_PASS;

exports.isEmailDeliveryConfigured = () => hasSmtpConfig;

let transporter = null;

if (hasSmtpConfig) {
  const port = parseInt(SMTP_PORT, 10);
  transporter = nodemailer.createTransport({
    host: SMTP_HOST,
    port,
    secure: port === 465, // Resend: true sur 465, false sur 587
    auth: {
      user: SMTP_USER,
      pass: SMTP_PASS,
    },
  });
} else {
  // ✅ DEV fallback : pas d’exception, juste log
  transporter = {
    sendMail: async (opts) => {
      console.log("[EMAIL DEV SKIPPED] SMTP non configuré.");
      console.log("To:", opts.to, "| Subject:", opts.subject);
      return { skipped: true };
    },
  };

  if (!isDev) {
    console.warn("[WARN] SMTP non configuré en production. Configure SMTP_HOST/PORT/USER/PASS.");
  }
}

// Helper function to render email templates
const renderTemplate = async (templateName, data) => {
  const templatePath = path.join(__dirname, "templates", `${templateName}.ejs`);
  return await ejs.renderFile(templatePath, data);
};

// Send email asynchronously
const sendEmail = async (to, subject, html, options = {}) => {
  try {
    const message = {
      from: FROM,
      to,
      subject,
      html,
    };

    if (options.attachments?.length) {
      message.attachments = options.attachments;
    }

    const result = await transporter.sendMail(message);
    if (result?.skipped) return false;
    console.log(`[EMAIL SENT] To: ${to} | Subject: ${subject}`);
    return true;
  } catch (error) {
    console.error(`[EMAIL ERROR] To: ${to} | Subject: ${subject} | Error: ${error.message}`);
    // Don't throw, just log
    return false;
  }
};

