const fs = require("fs");
const path = require("path");
const prisma = require("../../config/prisma");

const STATUSES = {
  PENDING: "OCR_PENDING",
  RUNNING: "OCR_EN_COURS",
  OK: "OCR_OK",
  SUSPECT: "OCR_SUSPECT",
  FAILED: "OCR_FAILED",
  UNSUPPORTED: "OCR_UNSUPPORTED",
};

const SUPPORTED_IMAGE_EXTENSIONS = new Set([
  ".bmp",
  ".jpeg",
  ".jpg",
  ".png",
  ".tif",
  ".tiff",
  ".webp",
]);

const DEFAULT_EXPECTED_AMOUNT = 2000;
const DEFAULT_EXPECTED_ACCOUNT = "IFRI";
const DEFAULT_LANG = "fra+eng";
const MAX_TEXT_LENGTH = 12000;

function normalizeText(value) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim()
    .toUpperCase();
}

function parseExpectedAmount() {
  const raw = process.env.QUITTANCE_EXPECTED_AMOUNT;
  const parsed = Number(String(raw || "").replace(/[^\d.]/g, ""));
  return Number.isFinite(parsed) && parsed > 0 ? parsed : DEFAULT_EXPECTED_AMOUNT;
}

function buildChecks(text) {
  const normalized = normalizeText(text);
  const expectedAmount = parseExpectedAmount();
  const expectedAccount = normalizeText(
    process.env.QUITTANCE_EXPECTED_ACCOUNT || DEFAULT_EXPECTED_ACCOUNT
  );
  const compactText = normalized.replace(/[,]/g, ".").replace(/\s+/g, " ");
  const amountPattern = String(expectedAmount).replace(/\B(?=(\d{3})+(?!\d))/g, "[ .]?");
  const amountRegex = new RegExp(`(^|[^0-9])${amountPattern}([^0-9]|$)`);

  const checks = {
    hasQuittanceKeyword: /\b(QUITTANCE|RECU|RECEPISSE|PAIEMENT|VERSEMENT)\b/.test(normalized),
    hasExpectedAmount: amountRegex.test(compactText),
    hasExpectedAccount: expectedAccount ? normalized.includes(expectedAccount) : true,
    hasDate: /\b\d{1,2}[\/\-.]\d{1,2}[\/\-.]\d{2,4}\b/.test(normalized),
  };

  const failures = Object.entries(checks)
    .filter(([, passed]) => !passed)
    .map(([name]) => name);

  return {
    checks,
    failures,
    expected: {
      amount: expectedAmount,
      account: expectedAccount,
    },
  };
}

function isSupportedImage(filePath) {
  return SUPPORTED_IMAGE_EXTENSIONS.has(path.extname(filePath || "").toLowerCase());
}

async function recognizeImage(filePath) {
  let createWorker;
  try {
    ({ createWorker } = require("tesseract.js"));
  } catch (error) {
    const err = new Error("tesseract.js n'est pas installe. Executez `npm install` dans backend.");
    err.cause = error;
    throw err;
  }

  const lang = process.env.OCR_LANG || DEFAULT_LANG;
  const worker = await createWorker(lang);
  try {
    const result = await worker.recognize(filePath);
    return {
      text: result?.data?.text || "",
      confidence: typeof result?.data?.confidence === "number" ? result.data.confidence : null,
    };
  } finally {
    await worker.terminate();
  }
}

async function extractText(filePath) {
  if (!filePath || !fs.existsSync(filePath)) {
    const err = new Error("Fichier de quittance introuvable.");
    err.status = STATUSES.FAILED;
    throw err;
  }

  if (!isSupportedImage(filePath)) {
    const err = new Error("Format non supporte par l'OCR local. Utilisez une image PNG/JPG/WebP lisible.");
    err.status = STATUSES.UNSUPPORTED;
    throw err;
  }

  return recognizeImage(filePath);
}

async function analyzeQuittancePiece(pieceId) {
  const piece = await prisma.pieceJustificative.findUnique({
    where: { id: pieceId },
    include: {
      demande: {
        include: {
          utilisateur: {
            select: { nom: true, prenom: true, numeroEtudiant: true },
          },
        },
      },
    },
  });

  if (!piece || piece.typePiece !== "QUITTANCE") return null;

  await prisma.pieceJustificative.update({
    where: { id: pieceId },
    data: {
      ocrStatut: STATUSES.RUNNING,
      ocrDetails: { startedAt: new Date().toISOString() },
    },
  });

  try {
    const { text, confidence } = await extractText(piece.url);
    const limitedText = text.slice(0, MAX_TEXT_LENGTH);
    const validation = buildChecks(limitedText);
    const hasUsableText = normalizeText(limitedText).length >= 20;
    const status =
      hasUsableText && validation.failures.length === 0 ? STATUSES.OK : STATUSES.SUSPECT;

    return prisma.pieceJustificative.update({
      where: { id: pieceId },
      data: {
        ocrStatut: status,
        ocrTexte: limitedText,
        ocrConfidence: confidence,
        ocrAnalyzedAt: new Date(),
        ocrDetails: {
          ...validation,
          hasUsableText,
          engine: "tesseract.js",
          language: process.env.OCR_LANG || DEFAULT_LANG,
        },
      },
    });
  } catch (error) {
    const status = error.status || STATUSES.FAILED;
    return prisma.pieceJustificative.update({
      where: { id: pieceId },
      data: {
        ocrStatut: status,
        ocrAnalyzedAt: new Date(),
        ocrDetails: {
          error: error.message,
          engine: "tesseract.js",
        },
      },
    });
  }
}

function enqueueQuittanceAnalysis(pieceId) {
  if (!pieceId) return;
  setImmediate(() => {
    analyzeQuittancePiece(pieceId).catch((error) => {
      console.error("[OCR] Analyse quittance echouee:", error.message);
    });
  });
}

async function enqueueQuittancesForDemande(demandeId) {
  const pieces = await prisma.pieceJustificative.findMany({
    where: { demandeId, typePiece: "QUITTANCE" },
    select: { id: true },
  });

  pieces.forEach((piece) => enqueueQuittanceAnalysis(piece.id));
  return pieces.length;
}

async function enqueuePendingQuittances(limit = 25) {
  const pieces = await prisma.pieceJustificative.findMany({
    where: {
      typePiece: "QUITTANCE",
      ocrStatut: { in: [STATUSES.PENDING, STATUSES.RUNNING] },
    },
    select: { id: true },
    take: limit,
    orderBy: { createdAt: "asc" },
  });

  pieces.forEach((piece) => enqueueQuittanceAnalysis(piece.id));
  return pieces.length;
}

module.exports = {
  STATUSES,
  buildChecks,
  analyzeQuittancePiece,
  enqueueQuittanceAnalysis,
  enqueueQuittancesForDemande,
  enqueuePendingQuittances,
};

