    institutionNom,
    institutionSigle,
    directeurNom,
    directeurTitre,
    directeurAdjointNom,
    directeurAdjointTitre,
    tamponDABase64,
    tamponDIRBase64,
    etudiantNom,
    etudiantPrenom,
    etudiantMatricule,
    etudiantFiliere,
    etudiantNiveau,
    reference,
    semestre,
    anneeAcademique,
    notes,
    qrBase64,
    dateGeneration,
    // Infos institution dynamiques
    domaine: instConfig.domaine,
    grade: instConfig.grade,
    mention: instConfig.mention,
    adresse: instConfig.adresse,
    siteWeb: instConfig.siteWeb,
    email: instConfig.email,
  });

  const browser = await getBrowser();
  let page = null;

  try {
    page = await browser.newPage();
    page.setDefaultNavigationTimeout(PDF_TIMEOUT_MS);
    page.setDefaultTimeout(PDF_TIMEOUT_MS);

    await page.setContent(html, {
      waitUntil: "domcontentloaded",
      timeout: PDF_TIMEOUT_MS,
    });
    await sleep(120);

    const fileName = `${reference}.pdf`;
    const outputPath = path.join(OUTPUT_DIR, fileName);

    log("Generating PDF:", outputPath);

    await page.pdf({
      path: outputPath,
      format: "A4",
      printBackground: true,
      preferCSSPageSize: true,
      scale: 0.95,
      margin: { top: 0, right: 0, bottom: 0, left: 0 },
      timeout: PDF_TIMEOUT_MS,
    });

    return outputPath;
  } catch (e) {
    const msg = e?.message || "Erreur génération PDF";
    log("PDF error:", msg);
    const err = new Error(`PDF_GENERATION_FAILED: ${msg}`);
    err.statusCode = 500;
    throw err;
  } finally {
    if (page) {
      try {
        await page.close();
      } catch {}
    }
  }
};

