  height: 28mm;
  border: 1px solid #888;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 7pt;
  text-align: center;
  color: #666;
  flex-shrink: 0;
  background: rgba(255,255,255,0.4);
}

/* ═══════════════════════════════════════
   TITRE DU RELEVÉ
═══════════════════════════════════════ */
.releve-title {
  text-align: center;
  font-size: 10.5pt;
  font-weight: bold;
  font-style: italic;
  text-decoration: underline;
  margin: 2.5mm 0 1.5mm 0;
  letter-spacing: 0.3px;
}

/* ═══════════════════════════════════════
   TABLEAU DES NOTES
═══════════════════════════════════════ */
.notes {
  width: 100%;
  border-collapse: collapse;
  font-size: 7.5pt;
}

/* En-tête tableau */
.notes thead tr {
  background-color: #1a3a5c;
  color: #ffffff;
}

.notes thead th {
  padding: 1.8mm 1mm;
  text-align: center;
  font-weight: bold;
  border: 0.5px solid #4a6a8c;
  font-size: 7.5pt;
  line-height: 1.2;
}

/* Lignes UE (unité d'enseignement) */
.row-ue td {
  background-color: #b8cce4;
  font-weight: bold;
  padding: 1.2mm 1.2mm;
  border: 0.5px solid #7a9ec0;
  font-size: 7.5pt;
  line-height: 1.2;
}

/* Lignes ECU (élément constitutif) */
.row-ecu td {
  background-color: #dce6f1;
  font-weight: normal;
  padding: 0.9mm 1.2mm;
  border: 0.5px solid #aac4e0;
  font-size: 7.2pt;
  line-height: 1.2;
}

.cell-code {
  text-align: center;
  width: 11%;
  font-size: 7pt;
}

.cell-code-ecu {
  text-align: center;
  width: 11%;
  font-size: 7pt;
  background-color: #dce6f1;
  border: 0.5px solid #aac4e0;
  padding: 0.9mm 1.2mm;
}

.cell-intitule {
  text-align: left;
  width: 37%;
}

.ecu-indent {
  padding-left: 6mm !important;
  font-style: italic;
}

.cell-num {
  text-align: center;
  width: 9%;
}

.cell-num-ecu {
  text-align: center;
  width: 9%;
  background-color: #dce6f1;
  border: 0.5px solid #aac4e0;
  padding: 0.9mm 1.2mm;
}

.cell-cote {
  text-align: center;
  width: 7%;
  font-weight: bold;
}

.cell-result {
  text-align: center;
  width: 26%;
  font-size: 7pt;
}

.cell-empty {
  background-color: #dce6f1;
  border: 0.5px solid #aac4e0;
}

/* ═══════════════════════════════════════
   BARRE RÉCAPITULATIVE
═══════════════════════════════════════ */
.summary-bar {
  display: flex;
  background-color: #1a3a5c;
  color: #ffffff;
  padding: 2mm 3mm;
  margin-top: 0;
  justify-content: space-around;
  align-items: center;
  border-top: none;
}

.sum-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 0.5mm;
}

.sum-label {
  font-size: 6.8pt;
  font-weight: normal;
  opacity: 0.9;
}

.sum-val {
  font-size: 9pt;
  font-weight: bold;
}

/* ═══════════════════════════════════════
   LÉGENDE
═══════════════════════════════════════ */
.legend {
  font-size: 5.5pt;
  color: #333;
  margin-top: 1.5mm;
  line-height: 1.5;
  text-align: justify;
  font-family: Arial, sans-serif;
}

/* ═══════════════════════════════════════
   DATE
═══════════════════════════════════════ */
.date-line {
  text-align: right;
  font-size: 8pt;
  margin: 2mm 0 1mm 0;
