const prisma = require("../../src/config/prisma");
const { createWorker } = require("tesseract.js");
const service = require("../../src/services/ocr/quittanceOcr.service");

describe("quittanceOcr.service", () => {
  beforeEach(() => {
    jest.clearAllMocks();
    delete process.env.QUITTANCE_EXPECTED_AMOUNT;
    delete process.env.QUITTANCE_EXPECTED_ACCOUNT;
  });

  it("marque OCR_OK quand le texte contient les signaux attendus", async () => {
    prisma.pieceJustificative.findUnique.mockResolvedValue({
      id: "piece-1",
      typePiece: "QUITTANCE",
      url: "uploads/quittance.jpg",
      demande: { utilisateur: {} },
    });
    prisma.pieceJustificative.update.mockImplementation(({ data }) =>
      Promise.resolve({ id: "piece-1", ...data })
    );
    createWorker.mockResolvedValue({
      recognize: jest.fn().mockResolvedValue({
        data: {
          text: "Quittance de paiement IFRI montant 2 000 FCFA le 12/06/2026",
          confidence: 91,
        },
      }),
      terminate: jest.fn().mockResolvedValue(),
    });

    const result = await service.analyzeQuittancePiece("piece-1");

    expect(result.ocrStatut).toBe(service.STATUSES.OK);
    expect(result.ocrConfidence).toBe(91);
    expect(result.ocrDetails.failures).toEqual([]);
  });

  it("marque OCR_SUSPECT quand des signaux metier manquent", async () => {
    prisma.pieceJustificative.findUnique.mockResolvedValue({
      id: "piece-1",
      typePiece: "QUITTANCE",
      url: "uploads/quittance.png",
      demande: { utilisateur: {} },
    });
    prisma.pieceJustificative.update.mockImplementation(({ data }) =>
      Promise.resolve({ id: "piece-1", ...data })
    );
    createWorker.mockResolvedValue({
      recognize: jest.fn().mockResolvedValue({
        data: { text: "Image floue sans montant identifiable", confidence: 42 },
      }),
      terminate: jest.fn().mockResolvedValue(),
    });

    const result = await service.analyzeQuittancePiece("piece-1");

    expect(result.ocrStatut).toBe(service.STATUSES.SUSPECT);
    expect(result.ocrDetails.failures).toContain("hasExpectedAmount");
  });

  it("marque OCR_UNSUPPORTED pour les formats non image", async () => {
    prisma.pieceJustificative.findUnique.mockResolvedValue({
      id: "piece-1",
      typePiece: "QUITTANCE",
      url: "uploads/quittance.pdf",
      demande: { utilisateur: {} },
    });
    prisma.pieceJustificative.update.mockImplementation(({ data }) =>
      Promise.resolve({ id: "piece-1", ...data })
    );

    const result = await service.analyzeQuittancePiece("piece-1");

    expect(result.ocrStatut).toBe(service.STATUSES.UNSUPPORTED);
    expect(createWorker).not.toHaveBeenCalled();
  });

  it("relance les quittances OCR en attente", async () => {
    const originalSetImmediate = global.setImmediate;
    global.setImmediate = (callback) => {
      callback();
      return 0;
    };

    prisma.pieceJustificative.findMany.mockResolvedValue([{ id: "piece-1" }]);
    prisma.pieceJustificative.findUnique.mockResolvedValue({
      id: "piece-1",
      typePiece: "QUITTANCE",
      url: "uploads/quittance.jpg",
      demande: { utilisateur: {} },
    });
    prisma.pieceJustificative.update.mockImplementation(({ data }) =>
      Promise.resolve({ id: "piece-1", ...data })
    );
    createWorker.mockResolvedValue({
      recognize: jest.fn().mockResolvedValue({
        data: {
          text: "Quittance de paiement IFRI montant 2 000 FCFA le 12/06/2026",
          confidence: 88,
        },
      }),
      terminate: jest.fn().mockResolvedValue(),
    });

    const count = await service.enqueuePendingQuittances();
    await Promise.resolve();

    expect(count).toBe(1);
    expect(prisma.pieceJustificative.findMany).toHaveBeenCalledWith(
      expect.objectContaining({
        where: expect.objectContaining({
          ocrStatut: { in: [service.STATUSES.PENDING, service.STATUSES.RUNNING] },
        }),
      })
    );

    global.setImmediate = originalSetImmediate;
  });
});

