            <path d="M18 6L6 18M6 6l12 12" />
          </svg>
        </button>

        <a href="/superadmin" className="sa-brand">
          <img src={logo} alt="EtuDocs" className="sa-brand__logo" />
          <span className="sa-brand__name">EtuDocs</span>
        </a>

        <nav className="sa-nav">
          {NAV.map((n) => (
