                        </button>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            <div className="sa-topbar__user">
              <div>
                <div className="sa-topbar__name">Super Admin</div>
                <div className="sa-topbar__meta">EtuDocs</div>
              </div>
              <div className="sa-topbar__avatar">SA</div>
            </div>
          </div>
        </header>

        <div className="sa-content">{children}</div>
      </div>
    </div>
  );
}

