const FORMAT_FIELDS = [
    ["N° Étudiant", "Numéro d'identification"],
    ["Nom",         "Nom complet de l'étudiant"],
    ["Code UE",     "Code de l'unité d'enseignement"],
    ["Intitulé UE", "Nom complet de l'UE"],
    ["Crédits",     "Nombre de crédits"],
    ["Note",        "Note obtenue (0-20)"],
    ["Résultat",    '"Validé" ou "Ajourné"'],
];

export default function SAAcademique() {
    const [tab, setTab] = useState("excel");
    const [file, setFile] = useState(null);
    const [uploading, setUploading] = useState(false);
    const [institution, setInstitution] = useState("IFRI");
    const [annee, setAnnee] = useState("2025-2026");
    const [uploadMsg, setUploadMsg] = useState(null);

    const handleFileChange = (e) => {
        const selected = e.target.files[0];
        if (selected) setFile(selected);
    };

    const handleUpload = async () => {
        if (!file) return;
        const formData = new FormData();
        formData.append("file", file);
        formData.append("institution", institution);
        formData.append("annee", annee);

        setUploading(true);
        setUploadMsg(null);
        try {
            await importNotes(formData);
            setUploadMsg({ type: "ok", text: "Import réussi." });
            setFile(null);
        } catch (err) {
            setUploadMsg({ type: "error", text: "Échec de l'import. Vérifiez le fichier et réessayez." });
        } finally {
            setUploading(false);
        }
    };

    const downloadModel = () => {
        window.open(`${import.meta.env.VITE_API_URL}/admin/model-notes`, '_blank');
    };

    return (
        <SALayout>
            <style>{css}</style>

            <div>
                <h2 className="sa-page-title">Gestion des données académiques</h2>
                <p className="sa-page-sub">Importez ou saisissez les notes et UE par institution</p>
            </div>

            {/* Filtres */}
            <div className="da-filter-card">
                <div className="da-filter-grid">
                    <div className="da-field">
                        <label>Institution</label>
                        <select className="da-select" value={institution} onChange={e => setInstitution(e.target.value)}>
                            <option>IFRI</option>
                            <option>EPAC</option>
                            <option>FSS</option>
                        </select>
                    </div>
                    <div className="da-field">
                        <label>Année académique</label>
                        <select className="da-select" value={annee} onChange={e => setAnnee(e.target.value)}>
                            <option>2025-2026</option>
                            <option>2024-2025</option>
                            <option>2023-2024</option>
                        </select>
                    </div>
                </div>
            </div>

            {/* Onglets */}
            <div className="da-tabs">
                <button className={`da-tab${tab === "excel"  ? " active" : ""}`} onClick={() => setTab("excel")}>Import Excel</button>
                <button className={`da-tab${tab === "manuel" ? " active" : ""}`} onClick={() => setTab("manuel")}>Saisie manuelle</button>
            </div>

            {/* Import Excel */}
            {tab === "excel" && (
                <div className="da-import-card">
                    <div className="da-import-title">Import via fichier Excel</div>

                    {uploadMsg && (
                        <div style={{
                            margin: "8px 0 4px",
                            padding: "10px 12px",
                            borderRadius: 8,
                            fontSize: 14,
                            color: uploadMsg.type === "ok" ? "#14532d" : "#991b1b",
                            background: uploadMsg.type === "ok" ? "#f0fdf4" : "#fef2f2",
                            border: `1px solid ${uploadMsg.type === "ok" ? "#bbf7d0" : "#fecaca"}`,
                        }}>
                            {uploadMsg.text}
                        </div>
                    )}

                    <button className="btn-dl-model" onClick={downloadModel}>
                        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                            <path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/>
                            <polyline points="7 10 12 15 17 10"/>
                            <line x1="12" y1="15" x2="12" y2="3"/>
                        </svg>
                        Télécharger le modèle Excel
                    </button>

                    <div className="da-format-box">
                        <div className="da-fmt-title">Format attendu :</div>
                        {FORMAT_FIELDS.map(([k, v], i) => (
                            <div key={i}>• <strong>{k} :</strong> {v}</div>
                        ))}
                    </div>

                    <div className="da-upload-zone" onClick={() => document.getElementById('fileInput').click()}>
                        <svg width="38" height="38" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
                            <polyline points="16 16 12 12 8 16"/>
                            <line x1="12" y1="12" x2="12" y2="21"/>
                            <path d="M20.39 18.39A5 5 0 0 0 18 9h-1.26A8 8 0 1 0 3 16.3"/>
                        </svg>
                        <div className="da-upload-title">
                            {file ? file.name : "Glissez-déposez votre fichier Excel ici"}
                        </div>
                        <div className="da-upload-sub">
                            {file ? `${(file.size / 1024).toFixed(2)} Ko` : "ou cliquez pour parcourir"}
                        </div>
                        <input
                            id="fileInput"
                            type="file"
                            accept=".xlsx,.xls"
                            style={{ display: "none" }}
                            onChange={handleFileChange}
                        />
                        <button className="btn-parcourir" onClick={(e) => { e.stopPropagation(); document.getElementById('fileInput').click(); }}>
                            Parcourir les fichiers
                        </button>
                        <div className="da-upload-hint">Format: .xlsx, .xls • Max: 10 Mo</div>
                    </div>

                    <div className="da-footer">
                        <button className="btn-annuler" onClick={() => setFile(null)}>Annuler</button>
                        <button
                            className={`btn-importer${file ? " ready" : ""}`}
                            onClick={handleUpload}
                            disabled={!file || uploading}
                        >
                            {uploading ? "Import en cours..." : "Importer les données"}
                        </button>
                    </div>
                </div>
            )}

            {/* Saisie manuelle */}
            {tab === "manuel" && (
                <div className="da-import-card">
                    <div className="da-import-title">Saisie manuelle des données</div>
                    <div className="da-saisie-placeholder">
                        <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="#cbd5e1" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" style={{ margin: "0 auto 12px" }}>
                            <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/>
                            <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/>
                        </svg>
                        Fonctionnalité en cours de développement.
                    </div>
                </div>
            )}
        </SALayout>
    );
}

