const getOcrBadgeClass = (status) => {
  if (status === "OCR_OK") return "ok";
  if (status === "OCR_SUSPECT") return "suspect";
  if (status === "OCR_FAILED" || status === "OCR_UNSUPPORTED") return "failed";
  return "pending";
};

const getOcrFailureText = (details) => {
  const failures = Array.isArray(details?.failures) ? details.failures : [];
  if (!failures.length) return null;
  return failures.map((key) => OCR_FAILURE_LABELS[key] || key).join(", ");
};

/* ─── Indicateur robustesse ───────────────────────────── */
function getStrength(pwd) {
  if (!pwd) return 0;
  let s = 0;
  if (pwd.length >= 8) s++;
  if (/[A-Z]/.test(pwd)) s++;
  if (/[0-9]/.test(pwd)) s++;
  if (/[^A-Za-z0-9]/.test(pwd)) s++;
  return s;
}

/* ─── Modal Modifier Mot de Passe (version complète) ─── */
function ModalMotDePasse({ onClose, onSuccess }) {
  const [actuel, setActuel] = useState("");
  const [nouveau, setNouveau] = useState("");
  const [confirmer, setConfirmer] = useState("");
  const [showActuel, setShowActuel] = useState(false);
  const [showNouveau, setShowNouveau] = useState(false);
  const [showConfirmer, setShowConfirmer] = useState(false);
  const [loading, setLoading] = useState(false);
  const [erreur, setErreur] = useState("");

  const strength = getStrength(nouveau);
  const strengthLabel = ["", "Faible", "Faible", "Moyen", "Fort"][strength];
  const strengthClass =
    strength <= 2 ? "weak" : strength === 3 ? "medium" : "strong";

  const handleSubmit = async () => {
    setErreur("");
    if (!actuel || !nouveau || !confirmer) {
      setErreur("Tous les champs sont obligatoires.");
      return;
    }
    if (nouveau.length < 8) {
      setErreur("Le nouveau mot de passe doit contenir au moins 8 caractères.");
      return;
    }
    if (nouveau !== confirmer) {
      setErreur("Les mots de passe ne correspondent pas.");
      return;
    }
    setLoading(true);
    try {
      const token = localStorage.getItem("token");
      const res = await fetch("/api/auth/change-password", {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          ancienMotDePasse: actuel,
          nouveauMotDePasse: nouveau,
        }),
      });
      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data?.message || "Mot de passe actuel incorrect.");
      }
      onSuccess("Mot de passe modifié avec succès ✓");
      onClose();
    } catch (e) {
      setErreur(e?.message || "Une erreur est survenue.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="pwd-modal-overlay" onClick={onClose}>
      <div className="pwd-modal" onClick={(e) => e.stopPropagation()}>
        <div className="pwd-modal__head">
          <div className="pwd-modal__title">
            <div className="pwd-modal__title-icon">
              <svg
                width="18"
                height="18"
                viewBox="0 0 24 24"
                fill="none"
                stroke="#1d4ed8"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <rect x="3" y="11" width="18" height="11" rx="2" ry="2" />
                <path d="M7 11V7a5 5 0 0 1 10 0v4" />
              </svg>
            </div>
            Modifier le mot de passe
          </div>
          <button className="pwd-modal__close" onClick={onClose}>
            ×
          </button>
        </div>

        <div className="pwd-modal__body">
          {/* Mot de passe actuel */}
          <div className="pwd-field">
            <label className="pwd-label">Mot de passe actuel</label>
            <div className="pwd-input-wrap">
              <input
                type={showActuel ? "text" : "password"}
                className="pwd-input"
                placeholder="••••••••"
                value={actuel}
                onChange={(e) => setActuel(e.target.value)}
                autoFocus
              />
              <button
                className="pwd-eye"
                type="button"
                onClick={() => setShowActuel((v) => !v)}
              >
                <EyeToggleIcon show={showActuel} />
              </button>
            </div>
          </div>

          {/* Nouveau mot de passe */}
          <div className="pwd-field">
            <label className="pwd-label">Nouveau mot de passe</label>
            <div className="pwd-input-wrap">
              <input
                type={showNouveau ? "text" : "password"}
                className="pwd-input"
                placeholder="••••••••"
                value={nouveau}
                onChange={(e) => setNouveau(e.target.value)}
              />
              <button
                className="pwd-eye"
                type="button"
                onClick={() => setShowNouveau((v) => !v)}
              >
                <EyeToggleIcon show={showNouveau} />
              </button>
            </div>
            {nouveau && (
              <>
                <div className="pwd-strength">
                  {[1, 2, 3, 4].map((i) => (
                    <div
                      key={i}
                      className={`pwd-strength__bar ${
                        strength >= i ? strengthClass : ""
                      }`}
                    />
                  ))}
                </div>
                <div className="pwd-hint">
                  {strengthLabel} — minimum 8 caractères
                </div>
              </>
            )}
          </div>

          {/* Confirmer */}
          <div className="pwd-field">
            <label className="pwd-label">
              Confirmer le nouveau mot de passe
            </label>
            <div className="pwd-input-wrap">
              <input
                type={showConfirmer ? "text" : "password"}
                className={`pwd-input ${
                  confirmer && confirmer !== nouveau ? "error" : ""
                }`}
                placeholder="••••••••"
                value={confirmer}
                onChange={(e) => setConfirmer(e.target.value)}
              />
              <button
                className="pwd-eye"
                type="button"
                onClick={() => setShowConfirmer((v) => !v)}
              >
                <EyeToggleIcon show={showConfirmer} />
              </button>
            </div>
            {confirmer && confirmer !== nouveau && (
              <div className="pwd-hint error">
                Les mots de passe ne correspondent pas
              </div>
            )}
          </div>

          {erreur && (
            <div
              style={{
                background: "#fef2f2",
                border: "1px solid #fecaca",
                borderRadius: "8px",
                padding: "10px 14px",
                fontSize: ".85rem",
                color: "#dc2626",
              }}
            >
              {erreur}
            </div>
          )}
        </div>

        <div className="pwd-modal__footer">
          <div className="pwd-btn-row">
            <button
              className="pwd-btn pwd-btn--ghost"
              onClick={onClose}
              disabled={loading}
            >
              Annuler
            </button>
            <button
              className="pwd-btn pwd-btn--primary"
              onClick={handleSubmit}
              disabled={loading || !actuel || !nouveau || !confirmer}
            >
              {loading ? "Enregistrement…" : "Enregistrer"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

const getReferenceDoc = (d) => {
  const doc = Array.isArray(d?.documents) ? d.documents[0] : null;
  return doc?.reference || d?.reference || d?.ref || "—";
};

// ── COMPOSANT PRINCIPAL ────────────────────────────────────
export default function ChefDivisionExamens() {
  const [view, setView] = useState("dashboard");
  const [selected, setSelected] = useState(null);
  const [search, setSearch] = useState("");
  const [pieces, setPieces] = useState(defaultPieces);
  const [globalComment, setGlobalComment] = useState("");
  const [modal, setModal] = useState(null);
  const [motifError, setMotifError] = useState("");
  const [generatedRef] = useState("");
  const [pieceBusy, setPieceBusy] = useState(null);
  const [preview, setPreview] = useState(null);
  const [genBusy, setGenBusy] = useState(false);

  const queryClient = useQueryClient();
  const { data: rawDemandes } = useDemandes();
  const { data: cdStats } = useChefDivisionStats();
  const demandes = useMemo(
    () => (Array.isArray(rawDemandes) ? rawDemandes : rawDemandes?.demandes ?? []),
    [rawDemandes]
  );
  const stats = useMemo(
    () => ({
      aSigner: cdStats?.attenteDirecteur ?? 0,
      signesCeMois: cdStats?.documentGenere ?? 0,
      refuses: cdStats?.rejetees ?? 0,
    }),
    [cdStats]
  );

  // État modal mot de passe + toast
  const [showPwd, setShowPwd] = useState(false);
  const [toast, setToast] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  const showToast = (msg, isError = false) => {
    setToast({ msg, isError });
    setTimeout(() => setToast(null), 3500);
  };

  const openTraitement = async (d) => {
    try {
      const full = await getDemandeById(d.id);
      setSelected(full);
      const mapped = (full?.pieces || []).map((p, idx) => ({
        id: p.id,
        name: p.typePiece,
        fileName: p.nom,
        url: p.url,
        num: `Pièce ${idx + 1}/${(full?.pieces || []).length || 1}`,
        status:
          p.statut === "VALIDEE"
            ? "valid"
            : p.statut === "REJETEE"
            ? "reject"
            : null,
        comment: p.commentaire || "",
        ocrStatut: p.ocrStatut || null,
        ocrConfidence: p.ocrConfidence ?? null,
        ocrDetails: p.ocrDetails || null,
      }));
      setPieces(mapped.length ? mapped : defaultPieces);
      setGlobalComment(full?.commentaireChefDivision || "");
      setMotifError("");
      setModal(null);
      setPreview(null);
      setView("traitement");
    } catch (e) {
      console.error(e);
      showToast("Impossible d'ouvrir le dossier.", true);
    }
  };

  useEffect(() => {
    return () => {
      if (preview?.url) URL.revokeObjectURL(preview.url);
    };
  }, [preview?.url]);

  const openPreview = async (piece) => {
    if (!piece?.id) {
      showToast("Fichier introuvable.", true);
      return;
    }
    try {
      const blob = await downloadPieceBlob(piece.id);
      setPreview({
        url: URL.createObjectURL(blob),
        name: piece.fileName || piece.name || "Document",
      });
    } catch (e) {
      console.error(e);
      showToast("Impossible d'ouvrir le fichier.", true);
    }
  };

  const setPieceStatus = async (id, status) => {
    const current = pieces.find((p) => p.id === id);
    const comment = (current?.comment || "").trim();
    setPieces((prev) => prev.map((p) => (p.id === id ? { ...p, status } : p)));
    setPieceBusy(id);
    try {
      await validerPiece(
        id,
        status === "valid" ? "VALIDEE" : "REJETEE",
        comment
      );
    } catch (e) {
      console.error(e);
      setPieces((prev) =>
        prev.map((p) => (p.id === id ? { ...p, status: null } : p))
      );
      showToast("Échec validation pièce.", true);
    } finally {
      setPieceBusy(null);
    }
  };

  const allValidated = useMemo(
    () => pieces.every((p) => p.status === "valid"),
    [pieces]
  );
  const anyRejected = useMemo(
    () => pieces.some((p) => p.status === "reject"),
    [pieces]
  );
  const allDecided = useMemo(
    () => pieces.every((p) => p.status !== null),
    [pieces]
  );

  const handleGenerate = async () => {
    if (!selected?.id) return;
    try {
      setGenBusy(true);
      await avancerDemande(selected.id, "GENERER_DOCUMENT");
      await queryClient.invalidateQueries({ queryKey: ["demandes"] });
      queryClient.invalidateQueries({ queryKey: ["statsChefDivision"] });
      setModal(null);
      setView("dashboard");
    } catch (e) {
      console.error(e);
      showToast(e?.message || "Erreur lors de la génération", true);
    } finally {
      setGenBusy(false);
    }
  };

  const handleReject = async () => {
    if (!selected?.id) return;
    if (globalComment.trim().length < 20) {
      setMotifError(
        "Le commentaire général est obligatoire (minimum 20 caractères)."
      );
      return;
    }
    try {
      setGenBusy(true);
      const notificationMessage = `Rejet de demande: ${globalComment.trim()}`;
      await avancerDemande(selected.id, "REJETER", notificationMessage);
      await queryClient.invalidateQueries({ queryKey: ["demandes"] });
      queryClient.invalidateQueries({ queryKey: ["statsChefDivision"] });
      setModal(null);
      setView("dashboard");
    } catch (e) {
      console.error(e);
      showToast(e?.message || "Erreur lors du rejet", true);
    } finally {
      setGenBusy(false);
    }
  };

