              <div className="motif-error" style={{ marginBottom: 12 }}>
                {motifError}
              </div>
            )}
            <div className="modal-actions" style={{ marginTop: 8 }}>
              <button
                className="modal-btn cancel"
                onClick={() => {
                  setModal(null);
                  setMotifError("");
                }}
                disabled={genBusy}
              >
                Annuler
              </button>
              <button
                className="modal-btn confirm-rej"
                onClick={handleReject}
                disabled={genBusy}
              >
                {genBusy && (
                  <span style={{display:"inline-block",width:13,height:13,border:"2px solid rgba(255,255,255,.35)",borderTopColor:"#fff",borderRadius:"50%",animation:"spin .6s linear infinite",verticalAlign:"middle",marginRight:6}} />
                )}
                {genBusy ? "Traitement..." : "✗ Confirmer le rejet"}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Preview fichier */}
      {preview && (
        <div className="modal-overlay" onClick={() => setPreview(null)}>
          <div
            className="modal"
            style={{ width: "900px", maxWidth: "95vw", height: "85vh" }}
            onClick={(e) => e.stopPropagation()}
          >
            <div className="modal-title">
              <EyeIcon /> {preview.name}
            </div>
            <div
              style={{
                height: "calc(85vh - 90px)",
                border: "1px solid var(--border)",
                borderRadius: 12,
                overflow: "hidden",
              }}
            >
              <iframe
                title="preview"
                src={preview.url}
                style={{ width: "100%", height: "100%", border: "none" }}
              />
            </div>
            <div className="modal-actions" style={{ marginTop: 14 }}>
              <button
                className="modal-btn cancel"
                onClick={() => setPreview(null)}
              >
                Fermer
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

