const getReferenceDoc = (d) => {
  const doc = Array.isArray(d?.documents) ? d.documents[0] : null;
  return doc?.reference || d?.reference || d?.ref || "—";
};

const normalizeStats = (st) => {
  // API retourne : { aTraiter, documentGenere, attenteDirecteur, disponibles, rejetees }
  const base = st ?? {};
  return {
    aTraiter: Number(base.aTraiter ?? 0),
    documentGenere: Number(base.documentGenere ?? 0),
    attenteDirecteur: Number(base.attenteDirecteur ?? 0),
    disponibles: Number(base.disponibles ?? 0),
    rejetees: Number(base.rejetees ?? 0),
  };
};

export default function DashboardCS() {
  const queryClient = useQueryClient();
  const [view, setView] = useState("dashboard"); // dashboard | traitement | success
  const [user, setUser] = useState(null);

  const [search, setSearch] = useState("");

  const { data: rawDemandes, isLoading: loading } = useDemandes();
  const { data: rawStats } = useChefDivisionStats();
  const demandes = useMemo(
    () => (Array.isArray(rawDemandes) ? rawDemandes : rawDemandes?.demandes ?? []),
    [rawDemandes]
  );
  const stats = useMemo(() => normalizeStats(rawStats), [rawStats]);

  const [selected, setSelected] = useState(null);
  const [pieces, setPieces] = useState([]);
  const [pieceBusy, setPieceBusy] = useState(null);
  const [globalComment, setGlobalComment] = useState("");
  const [modal, setModal] = useState(null); // null | "generate" | "reject"
  const [motifError, setMotifError] = useState("");
  const [preview, setPreview] = useState(null);
  const [generatedRef, setGeneratedRef] = useState("");

  // État pour le modal mot de passe et le toast
  const [showPwd, setShowPwd] = useState(false);
  const [toast, setToast] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  useEffect(() => {
    try {
      const raw = localStorage.getItem("etudocs_user");
      if (raw) setUser(JSON.parse(raw));
    } catch {}
  }, []);

  const showToast = (msg, isError = false) => {
    setToast({ msg, isError });
    setTimeout(() => setToast(null), 3500);
  };

  const logout = () => {
    try {
      localStorage.removeItem("etudocs_token");
      localStorage.removeItem("token");
      localStorage.removeItem("etudocs_user");
    } catch {}
    window.location.href = "/login";
  };

  const openTraitement = async (d) => {
    try {
      const full = await getDemandeById(d.id);
      setSelected(full);
      const mapped = (full?.pieces || []).map((p) => ({
        id: p.id,
        name: p.typePiece,
        fileName: p.nom,
        url: p.url,
        status:
          p.statut === "VALIDEE"
            ? "valid"
            : p.statut === "REJETEE"
            ? "reject"
            : null,
        comment: p.commentaire || "",
        ocrStatut: p.ocrStatut || null,
        ocrConfidence: p.ocrConfidence ?? null,
        ocrDetails: p.ocrDetails || null,
      }));
      setPieces(mapped);
      setGlobalComment(full?.commentaireChefDivision || "");
      setMotifError("");
      setPreview(null);
      setModal(null);
      setView("traitement");
    } catch (e) {
      console.error(e);
      showToast("Impossible d'ouvrir le dossier.", true);
    }
  };

  useEffect(() => {
    return () => {
      if (preview?.url) URL.revokeObjectURL(preview.url);
    };
  }, [preview?.url]);

  const openPreview = async (piece) => {
    if (!piece?.id) {
      showToast("Fichier introuvable.", true);
      return;
    }
    try {
      const blob = await downloadPieceBlob(piece.id);
      setPreview({
        url: URL.createObjectURL(blob),
        name: piece.fileName || piece.name || "Document",
      });
    } catch (e) {
      console.error(e);
      showToast("Impossible d'ouvrir le fichier.", true);
    }
  };

  const setPieceStatus = async (id, status) => {
    const current = pieces.find((p) => p.id === id);
    const comment = (current?.comment || "").trim();
    setPieces((prev) => prev.map((p) => (p.id === id ? { ...p, status } : p)));
    setPieceBusy(id);
    try {
      await validerPiece(
        id,
        status === "valid" ? "VALIDEE" : "REJETEE",
        comment
      );
    } catch (e) {
      console.error(e);
      setPieces((prev) =>
        prev.map((p) => (p.id === id ? { ...p, status: null } : p))
      );
      showToast("Échec validation pièce.", true);
    } finally {
      setPieceBusy(null);
    }
  };

  const allValidated = useMemo(
    () => pieces.every((p) => p.status === "valid"),
    [pieces]
  );
  const anyRejected = useMemo(
    () => pieces.some((p) => p.status === "reject"),
    [pieces]
  );
  const allDecided = useMemo(
    () => pieces.every((p) => p.status !== null),
    [pieces]
  );

  const handleGenerate = async () => {
    if (!selected?.id) return;
    try {
      await avancerDemande(selected.id, "GENERER_DOCUMENT");
      setGeneratedRef(getReferenceDoc(selected));
      await queryClient.invalidateQueries({ queryKey: ["demandes"] });
      queryClient.invalidateQueries({ queryKey: ["statsChefDivision"] });
      setModal(null);
      setView("success");
    } catch (e) {
      console.error(e);
      showToast(e?.message || "Erreur lors de la génération.", true);
    }
  };

  const handleReject = async () => {
    if (!selected?.id) return;
    if (globalComment.trim().length < 20) {
      setMotifError(
        "Le commentaire général est obligatoire (minimum 20 caractères)."
      );
      return;
    }
    try {
      const notificationMessage = `Rejet de demande: ${globalComment.trim()}`;
      await avancerDemande(selected.id, "REJETER", notificationMessage);
      await queryClient.invalidateQueries({ queryKey: ["demandes"] });
      queryClient.invalidateQueries({ queryKey: ["statsChefDivision"] });
      setModal(null);
      setView("dashboard");
    } catch (e) {
      console.error(e);
      showToast(e?.message || "Erreur lors du rejet.", true);
    }
  };

  const filtered = useMemo(() => {
    const q = (search || "").trim().toLowerCase();
    if (!q) return demandes;
    return demandes.filter((d) => {
      const nom = `${d?.utilisateur?.nom || ""} ${
        d?.utilisateur?.prenom || ""
      }`.toLowerCase();
      const ref = String(d?.ref || d?.id || "").toLowerCase();
      const mat = String(d?.utilisateur?.numeroEtudiant || "").toLowerCase();
      return nom.includes(q) || ref.includes(q) || mat.includes(q);
    });
  }, [demandes, search]);

  // ── Fragment commun : modal mot de passe + toast ─────
  const sharedOverlays = (
    <>
      {toast && (
        <div className={`sa-toast${toast.isError ? " sa-toast--error" : ""}`}>
          {toast.msg}
        </div>
      )}
      {showPwd && (
        <ModalMotDePasse
          onClose={() => setShowPwd(false)}
          onSuccess={(msg) => showToast(msg)}
        />
      )}
    </>
  );

  // ── DASHBOARD ────────────────────────────────────────
  if (view === "dashboard")
    return (
      <div className="agent-layout">
        <style>{css}</style>
        {sharedOverlays}
        <div className={`cs-overlay${sidebarOpen ? " cs-overlay--visible" : ""}`} onClick={() => setSidebarOpen(false)} />
        <Sidebar onLogout={logout} onChangePwd={() => setShowPwd(true)} open={sidebarOpen} onClose={() => setSidebarOpen(false)} collapsed={sidebarCollapsed} onToggleCollapse={() => setSidebarCollapsed(v => !v)} />
        <div className="agent-main" style={{ marginLeft: sidebarCollapsed ? 62 : 220, transition: 'margin-left 0.25s ease' }}>
          <Topbar user={user} onMenuToggle={() => setSidebarOpen(v => !v)} />
          <div className="agent-content">
            <div className="agent-page-header">
              <div>
                <h2 className="agent-page-title">Division de la Scolarité</h2>
                <p className="agent-page-sub">
                  Validez les pièces et générez les attestations d'inscription.
                </p>
              </div>
              <button
                className="btn-actualiser"
                onClick={() => {
                  queryClient.invalidateQueries({ queryKey: ["demandes"] });
                  queryClient.invalidateQueries({ queryKey: ["statsChefDivision"] });
                }}
                type="button"
              >
                <svg
                  width="16"
                  height="16"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="white"
                  strokeWidth="2.5"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <polyline points="23 4 23 10 17 10" />
                  <path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10" />
                </svg>
                Actualiser
              </button>
            </div>

            {/* Stats */}
            <div className="agent-stats">
              {[
                {
                  val: stats.aTraiter,
                  label: "À TRAITER",
                  bg: "#eff6ff",
                  icon: (
                    <svg
                      width="22"
                      height="22"
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="#1d4ed8"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    >
                      <circle cx="12" cy="12" r="10" />
                      <polyline points="12 6 12 12 16 14" />
                    </svg>
                  ),
                },
                {
                  val: stats.documentGenere,
                  label: "DOCS GÉNÉRÉS",
                  bg: "#f0fdf4",
                  icon: (
                    <svg
                      width="22"
                      height="22"
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="#16a34a"
                      strokeWidth="2.5"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    >
                      <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14" />
                      <polyline points="22 4 12 14.01 9 11.01" />
                    </svg>
                  ),
                },
                {
                  val: stats.rejetees,
                  label: "REJETÉES",
                  bg: "#fef2f2",
                  icon: (
                    <svg
                      width="22"
                      height="22"
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="#dc2626"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    >
                      <circle cx="12" cy="12" r="10" />
                      <line x1="15" y1="9" x2="9" y2="15" />
                      <line x1="9" y1="9" x2="15" y2="15" />
                    </svg>
                  ),
                },
                {
                  val: stats.attenteDirecteur,
                  label: "EN ATTENTE SIGNATURE",
                  bg: "#f5f3ff",
                  icon: (
                    <svg
                      width="22"
                      height="22"
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="#7c3aed"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    >
                      <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
                      <polyline points="14 2 14 8 20 8" />
                      <line x1="16" y1="13" x2="8" y2="13" />
                      <line x1="16" y1="17" x2="8" y2="17" />
                    </svg>
                  ),
                },
              ].map((s, i) => (
                <div className="agent-stat-card" key={i}>
                  <div
