              <table className="agent-table">
                <thead>
                  <tr>
                    <th>Référence</th>
                    <th>Étudiant</th>
                    <th>Document</th>
                    <th>Date soumission</th>
                    <th>Délai écoulé</th>
                    <th style={{ textAlign: "right" }}>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered.map((d) => {
                    const nom =
                      `${d.utilisateur?.nom || ""} ${
                        d.utilisateur?.prenom || ""
                      }`.trim() || "—";
                    const num = d.utilisateur?.numeroEtudiant || "—";
                    const { label, urgent } = delaiLabel(d.createdAt);
                    return (
                      <tr key={d.id}>
                        <td className="td-ref" data-label="Référence">
                          {getReferenceDoc(d)}
