                            <svg
                              width="13"
                              height="13"
                              viewBox="0 0 24 24"
                              fill="none"
                              stroke="white"
                              strokeWidth="2.5"
                              strokeLinecap="round"
                              strokeLinejoin="round"
                            >
                              <polygon points="5 3 19 12 5 21 5 3" />
                            </svg>
                            Traiter
                          </button>
                        </td>
                      </tr>
                    );
                  })}
                  {!loading && filtered.length === 0 && (
                    <tr>
                      <td
                        colSpan="6"
                        style={{
                          textAlign: "center",
                          padding: "32px",
                          color: "#94a3b8",
                          fontSize: ".9rem",
                        }}
                      >
                        Aucun dossier en attente
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    );

  // ── SUCCESS ──────────────────────────────────────────
  if (view === "success")
    return (
      <div className="agent-layout">
        <style>{css}</style>
        {sharedOverlays}
        <Sidebar onLogout={logout} onChangePwd={() => setShowPwd(true)} collapsed={sidebarCollapsed} onToggleCollapse={() => setSidebarCollapsed(v => !v)} />
        <div className="agent-main" style={{ marginLeft: sidebarCollapsed ? 62 : 220, transition: 'margin-left 0.25s ease' }}>
          <Topbar user={user} />
          <div
            className="agent-content"
            style={{ maxWidth: 580, margin: "60px auto" }}
          >
            <div className="success-card">
              <div className="success-icon">
                <svg
                  width="32"
