              <div
                style={{
                  marginTop: 24,
                  display: "flex",
                  justifyContent: "center",
                }}
              >
                <button
                  className="btn-traiter"
                  onClick={() => setView("dashboard")}
                  type="button"
                >
                  ← Retour au tableau de bord
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    );

  // ── TRAITEMENT ───────────────────────────────────────
  const nom = selected
    ? `${selected.utilisateur?.nom || ""} ${
        selected.utilisateur?.prenom || ""
      }`.trim() || "—"
    : "—";

  return (
    <div className="agent-layout">
      <style>{css}</style>
      {sharedOverlays}
      <Sidebar onLogout={logout} onChangePwd={() => setShowPwd(true)} collapsed={sidebarCollapsed} onToggleCollapse={() => setSidebarCollapsed(v => !v)} />
      <div className="agent-main" style={{ marginLeft: sidebarCollapsed ? 62 : 220, transition: 'margin-left 0.25s ease' }}>
        <Topbar user={user} />
        <div className="agent-content">
          {/* Back + header */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 14,
              marginBottom: 8,
            }}
          >
            <button
              className="back-btn"
              type="button"
              onClick={() => {
                setView("dashboard");
                setSelected(null);
                setPieces([]);
                setPreview(null);
                setModal(null);
              }}
            >
              ← Retour
            </button>
            <div>
              <h2 className="agent-page-title" style={{ fontSize: "1.3rem" }}>
                Traitement du dossier
              </h2>
              <div
                style={{
                  fontFamily: "monospace",
                  fontSize: ".8rem",
                  color: "var(--blue)",
                }}
              >
                {getReferenceDoc(selected)}
              </div>
            </div>
          </div>

          <div className="traitement-grid">
            {/* ── GAUCHE — Infos ── */}
            <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
              <div className="panel">
                <div className="panel-header">
                  <div className="panel-title">Informations étudiant</div>
                </div>
                <div className="panel-body">
                  <div className="info-row">
                    <div className="info-label">Nom complet</div>
                    <div className="info-value">
                      {selected?.utilisateur
                        ? `${selected.utilisateur.nom || ""} ${
                            selected.utilisateur.prenom || ""
                          }`.trim() || "—"
                        : "—"}
                    </div>
                  </div>
                  <div className="info-row">
                    <div className="info-label">N° Étudiant</div>
                    <div className="info-value">
                      {selected?.utilisateur?.numeroEtudiant || "—"}
                    </div>
                  </div>
                  <div className="info-row">
                    <div className="info-label">Filière / Niveau</div>
                    <div className="info-value">
                      {(() => {
                        const u = selected?.utilisateur;
                        const filiere =
                          u?.filiere ||
                          u?.etudiant?.filiere ||
                          u?.profile?.filiere ||
                          null;
                        const niveau =
                          u?.niveau ||
                          u?.etudiant?.niveau ||
                          u?.profile?.niveau ||
                          null;
                        if (!filiere && !niveau) return "—";
                        if (filiere && niveau) return `${filiere} — ${niveau}`;
                        return filiere || niveau;
                      })()}
                    </div>
                  </div>
                  <div className="info-row">
                    <div className="info-label">Institution</div>
                    <div className="info-value">
                      {selected?.institution?.nom || "IFRI — UAC"}
                    </div>
                  </div>
                  <div className="divider-h" />
                  <div className="info-row">
                    <div className="info-label">Type de document</div>
                    <div className="doc-type-pill">
                      <svg
                        width="14"
                        height="14"
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="2.2"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      >
                        <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
                        <polyline points="14 2 14 8 20 8" />
                      </svg>
                      {selected?.typeDocument === "ATTESTATION_INSCRIPTION"
                        ? "Attestation d'inscription"
                        : selected?.typeDocument === "RELEVE_NOTES"
                        ? "Relevé de notes"
                        : selected?.typeDocument || "—"}
                    </div>
                  </div>
                  {selected?.typeDocument === "ATTESTATION_INSCRIPTION" &&
                    selected?.anneeAcademique && (
                      <div className="info-row" style={{ marginTop: 10 }}>
                        <div className="info-label">Année académique</div>
                        <div
                          className="info-value"
                          style={{
                            background: "#f0fdf4",
                            color: "#16a34a",
                            border: "1px solid #bbf7d0",
                            padding: "5px 12px",
                            borderRadius: 7,
                            display: "inline-block",
                            fontWeight: 700,
                          }}
                        >
                          {selected.anneeAcademique}
                        </div>
                      </div>
                    )}
                  <div className="divider-h" />
                  <div className="info-row">
                    <div className="info-label">Date de soumission</div>
                    <div className="info-value">
                      {selected?.createdAt
                        ? new Date(selected.createdAt).toLocaleDateString(
                            "fr-FR",
                            { day: "2-digit", month: "long", year: "numeric" }
                          )
                        : "—"}
                    </div>
                  </div>
                  <div className="info-row">
                    <div className="info-label">Référence</div>
                    <div className="info-value mono">
                      {getReferenceDoc(selected)}
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* ── CENTRE — Pièces ── */}
            <div>
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  marginBottom: 14,
                }}
              >
                <div
                  style={{
                    fontWeight: 700,
                    fontSize: ".95rem",
                    color: "var(--navy)",
                  }}
                >
                  Vérification des pièces
                </div>
                <span className="badge blue">
                  {pieces.filter((p) => p.status === "valid").length}/
                  {pieces.length} validées
                </span>
              </div>

              {pieces.map((piece) => (
                <div className="piece-card" key={piece.id}>
                  <div className="piece-header">
                    <div className="piece-name">
                      <FileTextIcon />
                      {piece.name}
                    </div>
                    {piece.status === "valid" && (
                      <span className="badge green">
                        <CheckIcon /> Validée
                      </span>
                    )}
                    {piece.status === "reject" && (
                      <span className="badge red">
                        <XIcon /> Rejetée
                      </span>
                    )}
                    {piece.status === null && (
                      <span className="badge gray">En attente</span>
                    )}
                  </div>
                  <div className="piece-body">
                    {piece.name === "QUITTANCE" && piece.ocrStatut && (
                      <div className="ocr-box">
                        <div className="ocr-row">
                          <div className="ocr-title">Contrôle OCR quittance</div>
                          <span className={`ocr-badge ${getOcrBadgeClass(piece.ocrStatut)}`}>
                            {OCR_LABELS[piece.ocrStatut] || piece.ocrStatut}
                          </span>
                        </div>
                        <div className="ocr-meta">
                          {typeof piece.ocrConfidence === "number" && (
                            <span>Confiance : {Math.round(piece.ocrConfidence)}%. </span>
                          )}
                          {getOcrFailureText(piece.ocrDetails) && (
                            <span>Points à vérifier : {getOcrFailureText(piece.ocrDetails)}.</span>
                          )}
                          {piece.ocrDetails?.error && <span>{piece.ocrDetails.error}</span>}
                        </div>
                      </div>
                    )}
                    <button
                      className="btn-preview"
                      onClick={() => openPreview(piece)}
                      type="button"
                    >
                      <EyeIcon /> Consulter le fichier
                    </button>
                    <div className="piece-actions">
                      <button
                        disabled={pieceBusy === piece.id}
                        className={`btn-valider valid ${
                          piece.status === "valid" ? "selected" : ""
                        }`}
                        onClick={() => setPieceStatus(piece.id, "valid")}
                        type="button"
                      >
                        <CheckIcon /> Valider ✓
                      </button>
                      <button
                        disabled={pieceBusy === piece.id}
                        className={`btn-valider reject ${
                          piece.status === "reject" ? "selected" : ""
                        }`}
                        onClick={() => setPieceStatus(piece.id, "reject")}
                        type="button"
                      >
                        <XIcon /> Rejeter ✗
                      </button>
                    </div>
                  </div>
                </div>
              ))}

              {allValidated && (
                <div className="info-box green">
                  ✓ Toutes les pièces sont validées. Vous pouvez générer
                  l'attestation.
                </div>
              )}
              {anyRejected && !allValidated && (
                <div
                  className="info-box"
                  style={{
                    background: "#fef2f2",
                    color: "#991b1b",
                    border: "1px solid #fca5a5",
                  }}
                >
                  ⚠ Une ou plusieurs pièces rejetées. Rejetez la demande avec un
                  motif.
                </div>
              )}
            </div>

            {/* ── DROITE — Récap + Actions ── */}
            <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
              <div className="panel">
                <div className="panel-header">
                  <div className="panel-title">Récapitulatif</div>
                </div>
                <div className="panel-body">
                  {pieces.map((p) => (
                    <div
                      key={p.id}
                      className={`check-item ${
                        p.status === "valid"
                          ? "v"
                          : p.status === "reject"
                          ? "r"
                          : ""
                      }`}
                    >
                      <div className="check-name">{p.name}</div>
                      <div
                        className={`check-status ${
                          p.status === "valid"
                            ? "v"
                            : p.status === "reject"
                            ? "r"
                            : "p"
                        }`}
                      >
                        {p.status === "valid" ? (
                          <>
                            <CheckIcon /> Validée
                          </>
                        ) : p.status === "reject" ? (
                          <>
                            <XIcon /> Rejetée
                          </>
                        ) : (
                          "— En attente"
                        )}
                      </div>
                    </div>
                  ))}
                  <div className="divider" />
                  <div
                    style={{
                      fontSize: ".72rem",
                      fontWeight: 700,
                      color: "var(--muted)",
                      textTransform: "uppercase",
                      letterSpacing: ".05em",
                      marginBottom: 6,
                      display: "flex",
                      alignItems: "center",
                      gap: 4,
                    }}
                  >
                    Commentaire général{" "}
                    <span style={{ color: "var(--danger)" }}>*</span>
                  </div>
                  <textarea
                    className="comment"
                    rows={3}
                    placeholder="Commentaire obligatoire — sera envoyé à l'étudiant en cas de rejet (min. 20 caractères)..."
                    value={globalComment}
                    onChange={(e) => {
                      setGlobalComment(e.target.value);
                      setMotifError("");
                    }}
                  />
                  <div
                    style={{
                      fontSize: ".72rem",
                      color: "var(--text-muted)",
                      textAlign: "right",
                      marginTop: 3,
                    }}
                  >
                    {globalComment.length}/20 min
                  </div>
                  {motifError && (
                    <div
                      style={{
                        fontSize: ".75rem",
                        color: "var(--danger)",
                        marginTop: 4,
                      }}
                    >
                      {motifError}
                    </div>
                  )}
                </div>
              </div>

              <div className="panel">
                <div className="panel-header">
                  <div className="panel-title">Actions</div>
                </div>
                <div className="panel-body">
                  <button
                    className="btn-main generate"
                    disabled={!allValidated}
                    onClick={() => setModal("generate")}
                    type="button"
                  >
                    <SparkleIcon /> Valider et générer l'attestation
                  </button>
                  <button
                    className="btn-main reject-all"
                    type="button"
                    style={{
                      opacity: !allDecided || !anyRejected ? 0.4 : 1,
                      cursor:
                        !allDecided || !anyRejected ? "not-allowed" : "pointer",
                    }}
                    onClick={() => {
                      if (allDecided && anyRejected) setModal("reject");
                    }}
                  >
                    <XIcon /> Rejeter la demande
                  </button>
                  {!allDecided && (
                    <div className="info-box blue" style={{ marginTop: 4 }}>
                      Décidez pour chaque pièce avant de continuer.
                    </div>
                  )}
                  {allValidated && (
                    <div className="info-box green" style={{ marginTop: 4 }}>
                      Les données d'inscription seront injectées
                      automatiquement.
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Modal génération */}
      {modal === "generate" && (
        <div className="modal-overlay">
          <div className="modal">
            <div className="modal-title">
              <SparkleIcon /> Confirmer la génération
            </div>
            <div className="modal-body">
              Vous allez générer l'attestation d'inscription pour{" "}
              <strong>{nom}</strong>.<br />
              <br />
              Le système injectera automatiquement les données d'inscription
              (filière, niveau, année académique) dans le template officiel.{" "}
              <strong>Cette action est irréversible.</strong>
            </div>
            <div className="modal-actions">
              <button
                className="modal-btn cancel"
                onClick={() => setModal(null)}
                type="button"
              >
                Annuler
              </button>
              <button
                className="modal-btn confirm-gen"
                onClick={handleGenerate}
                type="button"
              >
                ✓ Confirmer
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Modal rejet */}
      {modal === "reject" && (
        <div className="modal-overlay">
          <div className="modal">
            <div className="modal-title">
              <XIcon /> Rejeter la demande
            </div>
            <div className="modal-body">
              Rejeter la demande de <strong>{nom}</strong>.<br />
              L'étudiant recevra une notification :{" "}
              <em>"Rejet de demande: {globalComment}"</em>
            </div>
            {motifError && (
              <div
                style={{
                  fontSize: ".75rem",
                  color: "var(--danger)",
                  marginBottom: 12,
                }}
              >
                {motifError}
              </div>
            )}
            <div className="modal-actions" style={{ marginTop: 8 }}>
              <button
                className="modal-btn cancel"
                type="button"
                onClick={() => {
                  setModal(null);
                  setMotifError("");
                }}
              >
                Annuler
              </button>
              <button
                className="modal-btn confirm-rej"
                onClick={handleReject}
                type="button"
              >
                ✗ Confirmer le rejet
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Preview fichier */}
      {preview && (
        <div className="modal-overlay" onClick={() => setPreview(null)}>
          <div
            className="modal"
            style={{ width: "900px", maxWidth: "95vw", height: "85vh" }}
            onClick={(e) => e.stopPropagation()}
          >
            <div className="modal-title">
              <EyeIcon /> {preview.name}
            </div>
            <div
              style={{
                height: "calc(85vh - 100px)",
                border: "1px solid var(--border)",
                borderRadius: 10,
                overflow: "hidden",
              }}
            >
              <iframe
                title="preview"
                src={preview.url}
                style={{ width: "100%", height: "100%", border: "none" }}
              />
            </div>
            <div className="modal-actions" style={{ marginTop: 12 }}>
              <button
                className="modal-btn cancel"
                onClick={() => setPreview(null)}
                type="button"
              >
                Fermer
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

