        title={collapsed ? "Agrandir le menu" : "Réduire le menu"}
      >
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
          <path d={collapsed ? "M9 18l6-6-6-6" : "M15 18l-6-6 6-6"} />
        </svg>
      </button>

      <button
        className="agent-sidebar__logout"
        onClick={onLogout}
        type="button"
        title={collapsed ? "Déconnexion" : undefined}
      >
        <svg
          width="18"
          height="18"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <path d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
        </svg>
        <span className="agent-sidebar__logout-label">Déconnexion</span>
      </button>
    </aside>
  );
}

// ── Topbar ────────────────────────────────────────────────
function Topbar({ user, onMenuToggle }) {
  const initials = useMemo(() => {
    const nom = user?.nom || "";
    const prenom = user?.prenom || "";
    return `${nom?.[0] || ""}${prenom?.[0] || ""}`.toUpperCase() || "DI";
  }, [user]);

  const name = user
    ? `${user.prenom || ""} ${user.nom || ""}`.trim()
    : "Directeur IFRI";

  const { notifications, unreadCount, markAllRead, deleteOne: deleteNotif, deleteAll: deleteAllNotifs } = useNotifications();
  const [notifOpen, setNotifOpen] = useState(false);
  const notifRef = useRef(null);
  useEffect(() => {
    const handler = (e) => { if (notifRef.current && !notifRef.current.contains(e.target)) setNotifOpen(false); };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, []);
  const fmtTime = (ts) => { try { return new Date(ts).toLocaleString("fr-FR", { day:"2-digit", month:"2-digit", hour:"2-digit", minute:"2-digit" }); } catch { return ""; } };

  return (
    <header className="agent-topbar">
      <div style={{display:"flex",alignItems:"center",gap:12}}>
        <button className="agent-topbar__burger" type="button" onClick={onMenuToggle} aria-label="Menu">
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 12h18M3 6h18M3 18h18"/></svg>
        </button>
        <div className="agent-topbar__role">Directeur — IFRI</div>
      </div>
      <div className="agent-topbar__right">
        <div ref={notifRef} style={{ position: "relative" }}>
          <button
            className="agent-topbar__notif"
            type="button"
            onClick={() => { setNotifOpen(v => !v); if (!notifOpen) markAllRead(); }}
            aria-label="Notifications"
          >
            <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9" />
              <path d="M13.73 21a2 2 0 0 1-3.46 0" />
            </svg>
            {unreadCount > 0 && <span className="agent-topbar__badge" />}
          </button>
          {notifOpen && (
            <div className="agent-notif-panel">
              <div className="agent-notif-panel__header">
                <span className="agent-notif-panel__title">Notifications</span>
                <button className="agent-notif-clear" type="button" onClick={deleteAllNotifs}>Tout supprimer</button>
              </div>
              <div className="agent-notif-list">
                {notifications.length === 0 ? (
                  <div className="agent-notif-empty">Aucune notification.</div>
                ) : notifications.map(n => (
                  <div className="agent-notif-item" key={n.id}>
                    <span className="agent-notif-dot" />
                    <div className="agent-notif-body">
                      <div className="agent-notif-msg">{n.message}</div>
                      <div className="agent-notif-meta">{fmtTime(n.createdAt)}</div>
                    </div>
                    <button className="agent-notif-del" type="button" onClick={() => deleteNotif(n.id)} aria-label="Supprimer">
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 6h18"/><path d="M8 6V4h8v2"/><path d="M19 6l-1 14H6L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/></svg>
                    </button>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
        <div>
          <div className="agent-topbar__name">{name}</div>
          <div className="agent-topbar__meta">IFRI</div>
        </div>
        <div className="agent-topbar__avatar">{initials}</div>
      </div>
    </header>
  );
}

// ── Icônes ────────────────────────────────────────────────
const EyeIcon = () => (
  <svg
    width="14"
    height="14"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
    <circle cx="12" cy="12" r="3" />
  </svg>
);

// ── Composant principal ───────────────────────────────────
const getReferenceDoc = (d) => {
  const doc = Array.isArray(d?.documents) ? d.documents[0] : null;
  return doc?.reference || d?.reference || d?.ref || "—";
};

export default function DashboardDI() {
  const queryClient = useQueryClient();
  const [user, setUser] = useState(null);
  const [search, setSearch] = useState("");
  const [busyRef, setBusyRef] = useState(null);
  const [preview, setPreview] = useState(null);
  const [showPwd, setShowPwd] = useState(false);
  const [toast, setToast] = useState(null);
  const [confirmRow, setConfirmRow] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  // Données via React Query
  const { data: rawDemandes, isLoading: loading, error } = useDemandes();
  const { data: rawStatsDI } = useStatsDI();

  // getDemandes() pour DIRECTEUR retourne uniquement les demandes
  // avec statut ATTENTE_SIGNATURE_DIRECTEUR — on déroule leurs documents
  // pour l'affichage du tableau uniquement.
  // Les stats chiffrées viennent du backend via getStatsDI() pour être exactes.
  const rows = useMemo(() => {
    const demandes = Array.isArray(rawDemandes)
      ? rawDemandes
      : rawDemandes?.demandes ?? [];
    const lignes = [];
    for (const d of demandes) {
      const docs = Array.isArray(d.documents) ? d.documents : [];
      if (docs.length === 0) {
        // Demande sans document encore lié : on affiche quand même la ligne
        lignes.push({
          reference: getReferenceDoc(d),
          etudiant: `${d.utilisateur?.prenom ?? ""} ${
            d.utilisateur?.nom ?? ""
          }`.trim(),
          typeDocument: d.typeDocument,
          semestre: null,
          createdAt: d.createdAt,
          demandeId: d.id,
          statut: d.statut,
        });
      } else {
        for (const doc of docs) {
          const sMatch = doc.reference?.match(/_S(\d+)(?:_|$)/);
          lignes.push({
            reference: doc.reference || getReferenceDoc(d),
            etudiant: `${d.utilisateur?.prenom ?? ""} ${
              d.utilisateur?.nom ?? ""
            }`.trim(),
            typeDocument: d.typeDocument,
            semestre: sMatch ? `S${sMatch[1]}` : null,
            createdAt: doc.createdAt || d.createdAt,
            demandeId: d.id,
            statut: doc.statut || d.statut,
          });
        }
      }
    }
    return lignes;
  }, [rawDemandes]);

  // Stats provenant du backend via getStatsDI()
  const stats = useMemo(
    () => rawStatsDI ?? { aSigner: 0, signesCeMois: 0, refuses: 0 },
    [rawStatsDI]
  );

  useEffect(() => {
    if (error) console.error(error);
  }, [error]);

  useEffect(() => {
    try {
      const raw =
        localStorage.getItem("etudocs_user") || localStorage.getItem("user");
      if (raw) setUser(JSON.parse(raw));
    } catch {}
  }, []);

  const showToast = (msg, isError = false) => {
    setToast({ msg, isError });
    setTimeout(() => setToast(null), 3500);
  };

  const logout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("etudocs_token");
    localStorage.removeItem("etudocs_user");
    localStorage.removeItem("user");
    window.location.href = "/";
  };

  const rafraichir = async () => {
    await queryClient.invalidateQueries({ queryKey: ["demandes"] });
    queryClient.invalidateQueries({ queryKey: ["statsDI"] });
  };

  const filtered = useMemo(() => {
    const q = (search || "").trim().toLowerCase();
    if (!q) return rows;
    return rows.filter(
      (r) =>
        (r.reference || "").toLowerCase().includes(q) ||
        (r.etudiant || "").toLowerCase().includes(q) ||
        (r.typeDocument || "").toLowerCase().includes(q)
    );
  }, [rows, search]);

  const openPreview = async (reference) => {
    if (!reference) return;
    try {
      const blob = await previewDocumentBlob(reference);
      const url = window.URL.createObjectURL(blob);
      setPreview({ url, name: reference });
    } catch (e) {
      showToast(e?.message || "Impossible d'ouvrir le document", true);
    }
  };

  const closePreview = () => {
    if (preview?.url) window.URL.revokeObjectURL(preview.url);
    setPreview(null);
  };

  const handleApprouver = async (row) => {
    if (!row?.reference) return;
    setBusyRef(row.reference);
    try {
      await avancerDocument(row.reference, "APPROUVER");
      showToast("Document approuvé avec succès ✓");
      await rafraichir();
    } catch (e) {
      showToast(e?.message || "Erreur lors de l'approbation", true);
    } finally {
      setBusyRef(null);
      setConfirmRow(null);
    }
  };

  // ── Fragment overlays partagés ─────────────────────────
  const sharedOverlays = (
    <>
      {toast && (
        <div className={`sa-toast${toast.isError ? " sa-toast--error" : ""}`}>
          {toast.msg}
        </div>
      )}
      {showPwd && (
        <ModalMotDePasse
          onClose={() => setShowPwd(false)}
          onSuccess={(msg) => showToast(msg)}
        />
      )}
    </>
  );

  // Stats issues du backend (getStatsDI) — fiables et correctement calculées
  // aSigner      = count(ATTENTE_SIGNATURE_DIRECTEUR) — demandes en attente
  // signesCeMois = count(DISPONIBLE ce mois-ci) — signées et livrées ce mois
  // refuses      = count(REJETEE ce mois-ci)
  const statsASigner = loading ? "…" : stats.aSigner;
  const statsValides = loading ? "…" : stats.signesCeMois;
  const statsRefuses = loading ? "…" : stats.refuses;

  return (
    <div className="agent-layout">
      <style>{css}</style>
      {sharedOverlays}
      <div className={`agent-overlay${sidebarOpen ? " agent-overlay--visible" : ""}`} onClick={() => setSidebarOpen(false)} />
      <Sidebar onLogout={logout} onChangePwd={() => setShowPwd(true)} open={sidebarOpen} onClose={() => setSidebarOpen(false)} collapsed={sidebarCollapsed} onToggleCollapse={() => setSidebarCollapsed(v => !v)} />
      <div className="agent-main" style={{ marginLeft: sidebarCollapsed ? 62 : 220, transition: 'margin-left 0.25s ease' }}>
        <Topbar user={user} onMenuToggle={() => setSidebarOpen(v => !v)} />
        <div className="agent-content">
          {/* En-tête page */}
          <div className="agent-page-header">
            <div>
              <h2 className="agent-page-title">Espace Directeur</h2>
              <p className="agent-page-sub">
                Signature finale des documents — par document.
              </p>
            </div>
            <button
              className="btn-actualiser"
              onClick={rafraichir}
              disabled={loading}
              type="button"
            >
              <svg
                width="16"
                height="16"
                viewBox="0 0 24 24"
                fill="none"
                stroke="white"
                strokeWidth="2.5"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <polyline points="23 4 23 10 17 10" />
                <path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10" />
              </svg>
              {loading ? "Chargement…" : "Actualiser"}
            </button>
          </div>

          {/* Stats */}
          <div className="agent-stats">
            {[
              {
                val: statsASigner,
                label: "À SIGNER",
                bg: "#eff6ff",
                icon: (
                  <svg
                    width="22"
                    height="22"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="#1d4ed8"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  >
                    <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
                    <polyline points="14 2 14 8 20 8" />
                    <line x1="16" y1="13" x2="8" y2="13" />
                    <line x1="16" y1="17" x2="8" y2="17" />
                  </svg>
                ),
              },
              {
                val: statsValides,
                label: "SIGNÉS CE MOIS",
                bg: "#f0fdf4",
                icon: (
                  <svg
                    width="22"
                    height="22"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="#16a34a"
                    strokeWidth="2.5"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  >
                    <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14" />
                    <polyline points="22 4 12 14.01 9 11.01" />
                  </svg>
                ),
              },
              {
                val: statsRefuses,
                label: "REFUSÉS",
                bg: "#fef2f2",
                icon: (
                  <svg
                    width="22"
                    height="22"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="#dc2626"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  >
                    <circle cx="12" cy="12" r="10" />
                    <line x1="15" y1="9" x2="9" y2="15" />
                    <line x1="9" y1="9" x2="15" y2="15" />
                  </svg>
                ),
              },
            ].map((s, i) => (
              <div className="agent-stat-card" key={i}>
                <div
                  className="agent-stat-card__icon"
                  style={{ background: s.bg }}
                >
                  {s.icon}
                </div>
                <div>
                  <div className="agent-stat-card__value">{s.val}</div>
                  <div className="agent-stat-card__label">{s.label}</div>
                </div>
              </div>
            ))}
          </div>

          {/* Table */}
          <div className="agent-table-card">
            <div className="agent-table-header">
              <div className="agent-table-title">
                Documents en attente de signature finale
                <span className="count-badge">{filtered.length}</span>
              </div>
              <div className="search-box">
                <svg
                  width="15"
                  height="15"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="#94a3b8"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <circle cx="11" cy="11" r="8" />
                  <line x1="21" y1="21" x2="16.65" y2="16.65" />
                </svg>
                <input
                  placeholder="Rechercher..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                />
              </div>
            </div>

            <table className="agent-table">
              <thead>
                <tr>
                  <th>Référence</th>
                  <th>Étudiant</th>
                  <th>Document</th>
                  <th>Semestre</th>
                  <th>Date</th>
                  <th>Statut</th>
                  <th style={{ textAlign: "right" }}>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filtered.map((r, i) => (
                  <tr key={r.reference ?? `row-${i}`}>
                    <td className="td-ref" data-label="Référence">{r.reference}</td>
                    <td data-label="Étudiant">
                      <div className="td-etudiant-name">{r.etudiant}</div>
                    </td>
                    <td className="td-doc" data-label="Document">{r.typeDocument}</td>
                    <td className="td-date" data-label="Semestre">{r.semestre ?? "—"}</td>
                    <td className="td-date" data-label="Date">{formatDate(r.createdAt)}</td>
                    <td data-label="Statut">
                      <span className="badge gray">{r.statut ?? "—"}</span>
                    </td>
                    <td data-label="" style={{ textAlign: "right" }}>
                      <div style={{ display: "inline-flex", gap: 8 }}>
                        <button
                          className="btn-outline"
                          onClick={() => openPreview(r.reference)}
                          type="button"
                        >
                          <EyeIcon /> Aperçu
                        </button>
                        <button
                          className="btn-traiter"
                          disabled={busyRef === r.reference}
                          onClick={() => setConfirmRow(r)}
                          type="button"
                        >
                          {busyRef === r.reference ? "…" : "Approuver"}
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
                {filtered.length === 0 && (
                  <tr>
                    <td
                      colSpan="7"
                      style={{
                        textAlign: "center",
                        padding: "32px",
                        color: "#94a3b8",
                        fontSize: ".9rem",
                      }}
                    >
                      Aucun document en attente de signature finale
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Modal confirmation approbation */}
      {confirmRow && (
        <div className="modal-overlay">
          <div className="modal">
            <div className="modal-title">
              <svg
                width="18"
                height="18"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2.5"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <polyline points="20 6 9 17 4 12" />
              </svg>
              Approuver le document
            </div>
            <div className="modal-body">
              Approuver le document <strong>{confirmRow.typeDocument}</strong>{" "}
              pour <strong>{confirmRow.etudiant}</strong> ?
            </div>
            <div className="modal-actions">
              <button
                className="modal-btn cancel"
                onClick={() => setConfirmRow(null)}
                type="button"
              >
                Annuler
              </button>
              <button
                className="modal-btn confirm-gen"
                onClick={() => handleApprouver(confirmRow)}
                type="button"
              >
                ✓ Confirmer
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Preview document */}
      {preview && (
        <div className="modal-overlay" onClick={closePreview}>
          <div
            className="modal"
            style={{ width: "900px", maxWidth: "95vw", height: "85vh" }}
            onClick={(e) => e.stopPropagation()}
          >
            <div className="modal-title">
              <EyeIcon /> {preview.name}
            </div>
            <div
              style={{
                height: "calc(85vh - 100px)",
                border: "1px solid var(--border)",
                borderRadius: 10,
                overflow: "hidden",
              }}
            >
              <iframe
                title="preview"
                src={preview.url}
                style={{ width: "100%", height: "100%", border: "none" }}
              />
            </div>
            <div className="modal-actions" style={{ marginTop: 12 }}>
              <button
                className="modal-btn cancel"
                onClick={closePreview}
                type="button"
              >
                Fermer
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// frontend/src/pages/DashboardEtudiant/Dashboard.jsx
import { useEffect, useMemo, useState } from "react";
import { useMe, useDemandes } from "../../hooks/queries";

import DashboardLayout from "../../components/DashboardEtudiant/DashboardLayout.jsx";
import StatCard from "../../components/DashboardEtudiant/Statcard.jsx";
import DemandRow from "../../components/DashboardEtudiant/Demandrow.jsx";

/* ─────────────────────────────────────────────────────────────
   STYLES GLOBAUX
───────────────────────────────────────────────────────────── */
const css = `
  @import url('https://fonts.googleapis.com/css2?family=Sora:wght@400;600;700;800&family=DM+Sans:wght@400;500&family=DM+Mono:wght@400;500&display=swap');

/* HERO BANNER */
