        ...d,
        title: uiTitle(d.typeDocument),
        ref_: d.reference,
        date: new Date(d.createdAt).toLocaleDateString("fr-FR", {
          day: "2-digit",
          month: "short",
          year: "numeric",
        }),
        status: uiStatus(d.statut),
      }));
  }, [demandes]);

