            <div key={s.key} className="stepper-step">
              <div className={`stepper-dot stepper-dot--${s.state}`}>
                {s.state === "done" && <SvgStepDone />}
                {s.state === "active" && (
                  <div
                    style={{
                      width: 10,
                      height: 10,
                      borderRadius: "50%",
                      background: "#2e7d32",
