export default function MesDemandes() {
  const navigate = useNavigate();

  const [filter, setFilter] = useState("Toutes");
  const [search, setSearch] = useState("");
  const { data, isLoading: loading, error: queryError } = useDemandes();
  const demandes = useMemo(() => (Array.isArray(data) ? data : []), [data]);
  const error = queryError
    ? queryError.message || "Échec du chargement des demandes."
    : "";
  const [detailItem, setDetailItem] = useState(null);
  const [resendLoading, setResendLoading] = useState(false);
  const { toast, showToast, hideToast } = useToast();

  const location = useLocation();

  // Auto-ouvre le détail si on arrive depuis le Dashboard
  useEffect(() => {
    const openId = location.state?.openId;
    if (!openId || demandes.length === 0) return;
    const found = demandes.find((d) => d.id === openId);
    if (found) setDetailItem(found);
  }, [demandes, location.state?.openId]);

  const counts = useMemo(() => {
    const base = {
      Toutes: 0,
      "En attente": 0,
      "En traitement": 0,
      Disponible: 0,
      Expirée: 0,
      Rejetée: 0,
    };
    base.Toutes = demandes.length;
    for (const d of demandes) {
      const s = computeUiStatus(d);
      if (base[s] !== undefined) base[s] += 1;
    }
    return base;
  }, [demandes]);

  const flatRows = useMemo(() => {
    return demandes.map((d) => {
      const docs = Array.isArray(d.documents) ? d.documents : [];
      const refs = docs.map((doc) => doc.reference).filter(Boolean);
      const ref = uiRef(refs.length ? refs.join(", ") : (d.reference || d.id));
      const type = labelType(d.typeDocument);
      const dateObj = d.createdAt ? new Date(d.createdAt) : null;
      const date = dateObj
        ? dateObj.toLocaleDateString("fr-FR", {
            day: "2-digit",
            month: "short",
            year: "numeric",
          })
        : "—";
      const status = computeUiStatus(d);
      const groupKey = groupKeyForDate(d.createdAt);

      return {
        raw: d,
        ref,
        type,
        date,
        status,
        groupKey,
        sortTs: dateObj ? dateObj.getTime() : 0,
        isExpired: status === "Expirée",
      };
    });
  }, [demandes]);

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();

    const list = flatRows.filter((row) => {
      const matchFilter = filter === "Toutes" || row.status === filter;
      const matchSearch =
        !q ||
        row.ref.toLowerCase().includes(q) ||
        row.type.toLowerCase().includes(q);
      return matchFilter && matchSearch;
    });

    list.sort((a, b) => b.sortTs - a.sortTs);
    return list;
  }, [flatRows, filter, search]);

  const grouped = useMemo(() => {
    const order = ["AUJOURDHUI", "SEMAINE", "MOIS", "ANNEE", "LONGTEMPS"];
    const map = new Map(order.map((k) => [k, []]));
    for (const r of filtered) {
      if (!map.has(r.groupKey)) map.set(r.groupKey, []);
      map.get(r.groupKey).push(r);
    }
    return order
      .map((k) => ({ key: k, label: groupLabel(k), items: map.get(k) || [] }))
      .filter((g) => g.items.length > 0);
  }, [filtered]);

  if (detailItem) {
    return (
      <DashboardLayout>
        <style>{css}</style>
        <DetailDemande
          demande={detailItem}
          onBack={() => setDetailItem(null)}
          resendLoading={resendLoading}
          onResendEmail={async () => {
            const reference = detailItem.documents?.[0]?.reference;
            if (!reference) return;
            try {
              setResendLoading(true);
              await resendDocumentEmail(reference);
              showToast("Email renvoye avec succes.", "success");
            } catch (e) {
              showToast(e?.message || "Impossible de renvoyer l'email.", "error");
            } finally {
              setResendLoading(false);
            }
          }}
          onNewReclamation={() =>
            navigate(
              `/dashboardEtu/nouvelle-reclamation?documentId=${detailItem.documents?.[0]?.id || ""}`
            )
          }
        />
        {toast && <Toast message={toast.message} type={toast.type} onClose={hideToast} />}
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout>
      <style>{css}</style>

      <div className="md-header">
        <div>
          <h2 className="md-title">Mes demandes</h2>
          <p className="md-sub">
            Suivez l'état de toutes vos demandes de documents
          </p>
        </div>

        <a href="/dashboardEtu/nouvelle" className="btn-new-orange">
          Nouvelle demande
        </a>
      </div>

      <div className="filter-bar">
        {FILTERS.map((f) => (
          <button
            key={f}
            type="button"
            className={`filter-tab${filter === f ? " active" : ""}`}
            onClick={() => setFilter(f)}
          >
            {f} ({counts[f] ?? 0})
          </button>
        ))}

        <div className="search-wrap">
          <svg
            width="15"
            height="15"
            viewBox="0 0 24 24"
            fill="none"
            stroke="#94a3b8"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <circle cx="11" cy="11" r="8" />
            <line x1="21" y1="21" x2="16.65" y2="16.65" />
          </svg>
          <input
            className="search-input"
            placeholder="Rechercher par référence ou type..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
      </div>

      {loading && <div className="state-box">Chargement des demandes…</div>}
      {!loading && error && (
        <div className="state-box state-error">{error}</div>
      )}

      {!loading && !error && (
        <div className="table-card">
          <table className="table">
            <thead>
              <tr>
                <th>Référence</th>
                <th>Type de document</th>
                <th>Date de soumission</th>
                <th>Statut</th>
                <th style={{ textAlign: "right" }}>Actions</th>
              </tr>
            </thead>

            <tbody>
              {grouped.length === 0 ? (
                <tr>
                  <td
                    colSpan={5}
                    style={{ padding: "18px 20px", color: "#475569" }}
                  >
                    Aucune demande trouvée.
                  </td>
                </tr>
              ) : (
                grouped.flatMap((g) => {
                  const headerRow = (
                    <tr key={`g-${g.key}`} className="group-row">
                      <td colSpan={4}>
                        <span className="group-title">{g.label}</span>
                      </td>
                      <td className="group-count">{g.items.length}</td>
                    </tr>
                  );

                  const rows = g.items.map((d) => (
                    <tr
                      key={d.raw.id}
                      className={d.isExpired ? "row-expired" : ""}
                    >
                      <td className="td-ref" data-label="Réf.">{d.ref}</td>
                      <td className="td-type" data-label="Type">{d.type}</td>
                      <td className="td-date" data-label="Date">{d.date}</td>
                      <td data-label="Statut">
                        <span className={`badge ${badgeClass(d.status)}`}>
                          {d.status}
                        </span>
                      </td>
                      <td data-label="">
                        <div className="td-actions">
                          <button
                            className="btn-view"
                            type="button"
                            onClick={() => setDetailItem(d.raw)}
                          >
                            <IcoEye /> Voir détails
                          </button>
                        </div>
                      </td>
                    </tr>
                  ));

                  return [headerRow, ...rows];
                })
              )}
            </tbody>
          </table>
        </div>
      )}
    </DashboardLayout>
  );
}

