                      {p.nom || "Fichier uploadé"}
                    </div>
                  </div>
                  <span className="sa-piece-tag">{p.statut || "SOUMISE"}</span>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="sa-modal__footer">
          <div className="sa-btn-row">
            <button className="sa-btn sa-btn--ghost" onClick={onClose}>
              Fermer
            </button>
