              className="sa-btn sa-btn--primary"
              onClick={handleTransmettre}
              disabled={loading || !peutTransmettre}
            >
              {loading ? "Envoi…" : "Transmettre au SG →"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
