                      colSpan="6"
                      style={{
                        textAlign: "center",
                        padding: "32px",
                        color: "#94a3b8",
                        fontSize: ".9rem",
                      }}
                    >
                      Chargement…
                    </td>
                  </tr>
                ) : filtered.length === 0 ? (
                  <tr>
                    <td
                      colSpan="6"
                      style={{
                        textAlign: "center",
                        padding: "32px",
                        color: "#94a3b8",
                        fontSize: ".9rem",
                      }}
                    >
                      {search
                        ? "Aucune demande trouvée"
                        : "Aucune demande en attente"}
                    </td>
                  </tr>
                ) : (
                  filtered.map((d) => {
                    const u = d.utilisateur || {};
                    return (
                      <tr key={d.id || getReferenceDoc(d)}>
                        <td className="td-ref">{getReferenceDoc(d)}</td>
                        <td>
                          <div className="td-etudiant-name">
                            {u.prenom} {u.nom}
                          </div>
                          <div className="td-etudiant-num">
                            {u.numeroEtudiant || "—"}
                          </div>
                        </td>
                        <td className="td-doc">
                          {TYPE_LABEL[d.typeDocument] || d.typeDocument}
                        </td>
                        <td className="td-date">{fmtDate(d.createdAt)}</td>
                        <td>
                          <span className={`badge ${badgeClass(d.statut)}`}>
                            {badgeLabel(d.statut)}
                          </span>
                        </td>
                        <td>
                          <div className="td-actions">
                            <button
                              className="btn-verifier"
                              onClick={() => setSelected(d)}
                            >
                              <svg
                                width="16"
                                height="16"
                                viewBox="0 0 24 24"
                                fill="none"
                                strokeWidth="2"
                                strokeLinecap="round"
                                strokeLinejoin="round"
                              >
                                <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
                                <circle cx="12" cy="12" r="3" />
                              </svg>
                              Vérifier
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}

