/* ── HELPERS ── */
const formatDate = (iso) => {
  if (!iso) return "—";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "—";
  return d.toLocaleString();
};
const getEtudiantLabel = (d) => {
  const u = d?.utilisateur;
  const fallback = d?.etudiant || d?.nomEtudiant || "";
  if (!u) return fallback || "—";
  const full = `${u?.prenom ?? ""} ${u?.nom ?? ""}`.trim();
  return full || fallback || "—";
};
const getNumeroEtudiant = (d) =>
  d?.utilisateur?.numeroEtudiant || d?.numeroEtudiant || d?.num || "—";
const getReferenceDoc = (d) => {
  const doc = Array.isArray(d?.documents) ? d.documents[0] : null;
  return doc?.reference || d?.reference || d?.ref || "—";
};

/* ── Force du mot de passe ── */
function getStrength(pwd) {
  if (!pwd) return 0;
  let s = 0;
  if (pwd.length >= 8) s++;
  if (/[A-Z]/.test(pwd)) s++;
  if (/[0-9]/.test(pwd)) s++;
  if (/[^A-Za-z0-9]/.test(pwd)) s++;
  return s;
}

/* ── Modal Modifier Mot de Passe ── */
function ModalMotDePasse({ onClose, onSuccess }) {
  const [actuel, setActuel] = useState("");
  const [nouveau, setNouveau] = useState("");
  const [confirmer, setConfirmer] = useState("");
  const [showA, setShowA] = useState(false);
  const [showN, setShowN] = useState(false);
  const [showC, setShowC] = useState(false);
  const [loading, setLoading] = useState(false);
  const [erreur, setErreur] = useState("");

  const strength = getStrength(nouveau);
  const strengthLabel = ["", "Faible", "Faible", "Moyen", "Fort"][strength];
  const strengthClass =
    strength <= 2 ? "weak" : strength === 3 ? "medium" : "strong";

  const EyeIcon = ({ show }) => (
    <svg
      width="16"
      height="16"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      {show ? (
        <>
          <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94" />
          <path d="M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19" />
          <line x1="1" y1="1" x2="23" y2="23" />
        </>
      ) : (
        <>
          <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
          <circle cx="12" cy="12" r="3" />
        </>
      )}
    </svg>
  );

  const handleSubmit = async () => {
    setErreur("");
    if (!actuel || !nouveau || !confirmer) {
      setErreur("Tous les champs sont obligatoires.");
      return;
    }
    if (nouveau.length < 8) {
      setErreur("Le nouveau mot de passe doit contenir au moins 8 caractères.");
      return;
    }
    if (nouveau !== confirmer) {
      setErreur("Les mots de passe ne correspondent pas.");
      return;
    }
    setLoading(true);
    try {
      const token =
        localStorage.getItem("token") || localStorage.getItem("etudocs_token");
      const res = await fetch("/api/auth/change-password", {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          ancienMotDePasse: actuel,
          nouveauMotDePasse: nouveau,
        }),
      });
      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data?.message || "Mot de passe actuel incorrect.");
      }
      onSuccess("Mot de passe modifié avec succès ✓");
      onClose();
    } catch (e) {
      setErreur(e?.message || "Une erreur est survenue.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="pwd-overlay" onClick={onClose}>
      <div className="pwd-modal" onClick={(e) => e.stopPropagation()}>
        <div className="pwd-modal__head">
          <div className="pwd-modal__title">
            <div className="pwd-modal__title-icon">
              <svg
                width="18"
                height="18"
                viewBox="0 0 24 24"
                fill="none"
                stroke="#1d4ed8"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <rect x="3" y="11" width="18" height="11" rx="2" ry="2" />
                <path d="M7 11V7a5 5 0 0 1 10 0v4" />
              </svg>
            </div>
            Modifier le mot de passe
          </div>
          <button className="pwd-modal__close" onClick={onClose}>
            ×
          </button>
        </div>

        <div className="pwd-modal__body">
          {/* Actuel */}
          <div className="pwd-field">
            <label className="pwd-label">Mot de passe actuel</label>
            <div className="pwd-input-wrap">
              <input
                type={showA ? "text" : "password"}
                className="pwd-input"
                placeholder="••••••••"
                value={actuel}
                onChange={(e) => setActuel(e.target.value)}
                autoFocus
              />
              <button
                className="pwd-eye"
                type="button"
                onClick={() => setShowA((v) => !v)}
              >
                <EyeIcon show={showA} />
              </button>
            </div>
          </div>

          {/* Nouveau */}
          <div className="pwd-field">
            <label className="pwd-label">Nouveau mot de passe</label>
            <div className="pwd-input-wrap">
              <input
                type={showN ? "text" : "password"}
                className="pwd-input"
                placeholder="••••••••"
                value={nouveau}
                onChange={(e) => setNouveau(e.target.value)}
              />
              <button
                className="pwd-eye"
                type="button"
                onClick={() => setShowN((v) => !v)}
              >
                <EyeIcon show={showN} />
              </button>
            </div>
            {nouveau && (
              <>
                <div className="pwd-strength">
                  {[1, 2, 3, 4].map((i) => (
                    <div
                      key={i}
                      className={`pwd-strength__bar ${
                        strength >= i ? strengthClass : ""
                      }`}
                    />
                  ))}
                </div>
                <div className="pwd-hint">
                  {strengthLabel} — minimum 8 caractères
                </div>
              </>
            )}
          </div>

          {/* Confirmer */}
          <div className="pwd-field">
            <label className="pwd-label">
              Confirmer le nouveau mot de passe
            </label>
            <div className="pwd-input-wrap">
              <input
                type={showC ? "text" : "password"}
                className={`pwd-input ${
                  confirmer && confirmer !== nouveau ? "pwd-err" : ""
                }`}
                placeholder="••••••••"
                value={confirmer}
                onChange={(e) => setConfirmer(e.target.value)}
              />
              <button
                className="pwd-eye"
                type="button"
                onClick={() => setShowC((v) => !v)}
              >
                <EyeIcon show={showC} />
              </button>
            </div>
            {confirmer && confirmer !== nouveau && (
              <div className="pwd-hint pwd-hint-err">
                Les mots de passe ne correspondent pas
              </div>
            )}
          </div>

          {erreur && (
            <div
              style={{
                background: "#fef2f2",
                border: "1px solid #fecaca",
                borderRadius: "8px",
                padding: "10px 14px",
                fontSize: ".85rem",
                color: "#dc2626",
              }}
            >
              {erreur}
            </div>
          )}
        </div>

        <div className="pwd-modal__footer">
          <div className="pwd-btn-row">
            <button
              className="pwd-btn pwd-btn--ghost"
              onClick={onClose}
              disabled={loading}
            >
              Annuler
            </button>
            <button
              className="pwd-btn pwd-btn--primary"
              onClick={handleSubmit}
              disabled={loading || !actuel || !nouveau || !confirmer}
            >
              {loading ? "Enregistrement…" : "Enregistrer"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ── COMPOSANT PRINCIPAL ── */
export default function DashboardSG() {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [searchQuery, setSearchQuery] = useState("");
  const [busyId, setBusyId] = useState(null);
  const [preview, setPreview] = useState(null);
  const [showPwd, setShowPwd] = useState(false);
  const [toast, setToast] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const { notifications, unreadCount, markAllRead, deleteOne: deleteNotif, deleteAll: deleteAllNotifs } = useNotifications();
  const [notifOpen, setNotifOpen] = useState(false);
  const notifRef = useRef(null);
  useEffect(() => {
    const handler = (e) => { if (notifRef.current && !notifRef.current.contains(e.target)) setNotifOpen(false); };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, []);
  const fmtTime = (ts) => { try { return new Date(ts).toLocaleString("fr-FR", { day:"2-digit", month:"2-digit", hour:"2-digit", minute:"2-digit" }); } catch { return ""; } };
  const { data: rawDemandes, isLoading: loading, error } = useDemandes();
  const { data: statsExternes = { transmises: 0, rejetees: 0 } } = useStatsSG();

  const demandes = useMemo(() => {
    const list = Array.isArray(rawDemandes)
      ? rawDemandes
      : rawDemandes?.demandes ?? [];
    return list
      .filter((d) => d.statut === "TRANSMISE_SECRETAIRE_ADJOINT")
      .sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));
  }, [rawDemandes]);

  const showToast = useCallback((msg, isError = false) => {
    setToast({ msg, isError });
    setTimeout(() => setToast(null), 3500);
  }, []);

  useEffect(() => {
    if (error) showToast(error?.message || "Erreur chargement demandes", true);
  }, [error, showToast]);

  const filtered = useMemo(() => {
    const q = (searchQuery || "").trim().toLowerCase();
    if (!q) return demandes;
    return demandes.filter((d) => {
      const ref = (getReferenceDoc(d) || "").toLowerCase();
      const etu = (getEtudiantLabel(d) || "").toLowerCase();
      const num = (getNumeroEtudiant(d) || "").toLowerCase();
      const type = ((d?.typeDocument || "") + "").toLowerCase();
      return (
        ref.includes(q) ||
        etu.includes(q) ||
        num.includes(q) ||
        type.includes(q)
      );
    });
  }, [demandes, searchQuery]);

  const handleTransmettre = async (demande) => {
    if (!demande?.id) return;
    setBusyId(demande.id);
    try {
      await avancerDemande(demande.id, "TRANSMETTRE");
      await queryClient.invalidateQueries({ queryKey: ["demandes"] });
      queryClient.invalidateQueries({ queryKey: ["statsSG"] });
    } catch (e) {
      console.error(e);
      showToast(e?.message || "Erreur transmission", true);
    } finally {
      setBusyId(null);
    }
  };

  // eslint-disable-next-line no-unused-vars
  const openPreview = async (demande) => {
    const reference = getReferenceDoc(demande);
    if (!reference || reference === "—") {
      showToast("Aucune référence de document trouvée.", true);
      return;
    }
    try {
      const blob = await downloadDocumentBlob(reference);
      const url = window.URL.createObjectURL(blob);
      setPreview({ url, name: reference });
    } catch (e) {
      console.error(e);
      showToast(e?.message || "Impossible d'ouvrir le document", true);
    }
  };

  const closePreview = () => {
    if (preview?.url) window.URL.revokeObjectURL(preview.url);
    setPreview(null);
  };

  const handleLogout = () => {
    ["etudocs_token", "token", "etudocs_user"].forEach((k) => {
      localStorage.removeItem(k);
      sessionStorage.removeItem(k);
    });
    navigate("/", { replace: true });
  };

  return (
    <>
      <style>{css}</style>

      {/* Toast */}
      {toast && (
        <div className={`sg-toast${toast.isError ? " sg-toast--error" : ""}`}>
          {toast.msg}
        </div>
      )}

      {/* Modal mot de passe */}
      {showPwd && (
        <ModalMotDePasse
          onClose={() => setShowPwd(false)}
          onSuccess={(msg) => showToast(msg)}
        />
      )}

      <div className="sg-layout">
        <div className={`sg-overlay${sidebarOpen ? " sg-overlay--visible" : ""}`} onClick={() => setSidebarOpen(false)} />

        {/* ── SIDEBAR ── */}
        <aside className={`sg-sidebar${sidebarOpen ? " sg-sidebar--open" : ""}${sidebarCollapsed ? " sg-sidebar--collapsed" : ""}`}>
          <a href="/" className="sg-sidebar__brand">
            <div className="sg-sidebar__brand-icon">
              <img
                src={logo}
                alt="EtuDocs"
                style={{ width: 52, height: 52, objectFit: "contain" }}
              />
            </div>
            <span className="sg-sidebar__brand-text">EtuDocs</span>
          </a>

          <nav className="sg-sidebar__nav">
