                  {unreadCount > 0 && <span className="sg-topbar__notif-dot" />}
                </button>
                {notifOpen && (
                  <div className="sg-notif-panel">
                    <div className="sg-notif-panel__header">
                      <span className="sg-notif-panel__title">Notifications</span>
                      <button className="sg-notif-clear" type="button" onClick={deleteAllNotifs}>Tout supprimer</button>
                    </div>
                    <div className="sg-notif-list">
                      {notifications.length === 0 ? (
