// Règles de mot de passe — miroir exact de
// backend/src/modules/auth/security/validatePassword.js
// (toute évolution doit être répercutée des deux côtés)

export const PASSWORD_RULES = [
  { key: "length", label: "Au moins 8 caractères", test: (p) => p.length >= 8 },
  { key: "upper", label: "Au moins une majuscule", test: (p) => /[A-Z]/.test(p) },
  {
    key: "special",
    label: "Au moins un caractère spécial",
    test: (p) => /[^A-Za-z0-9]/.test(p),
  },
];

/**
 * Indique si un mot de passe respecte toutes les règles.
 * @param {string} p
 * @returns {boolean}
 */
export const isPasswordValid = (p) =>
  PASSWORD_RULES.every((r) => r.test(String(p || "")));

/**
 * Force indicative (0..3) = nombre de règles satisfaites.
 * @param {string} p
 * @returns {number}
 */
export const passwordStrength = (p) =>
  p ? PASSWORD_RULES.filter((r) => r.test(String(p))).length : 0;

/**
 * Route du tableau de bord par défaut selon le rôle (et le service pour CHEF_DIVISION).
 * Source de vérité partagée entre la redirection post-login et le guard de routes.
 * @param {{ role?: string, service?: string }} user
 * @returns {string}
 */
export const routeForUser = (user) => {
  const role = user?.role;
  if (role === "ETUDIANT")            return "/dashboardEtu";
  if (role === "SUPER_ADMIN")         return "/superadmin";
  if (role === "SECRETAIRE_ADJOINT")  return "/dashboardsa";
  if (role === "SECRETAIRE_GENERAL")  return "/dashboardsg";
  if (role === "CHEF_DIVISION") {
    return user?.service === "SCOLARITE" ? "/dashboardsc" : "/dashboardce";
  }
  if (role === "DIRECTEUR_ADJOINT")   return "/dashboardda";
  if (role === "DIRECTEUR")           return "/dashboarddi";
  return "/dashboardsa";
};

